actions.script:
lastTaskNum = 0
const prefix = baseWorkEffortId + '-'
for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'like', prefix + '%')
        .selectField('workEffortId').disableAuthz().list()) {
    const rest = String(row.workEffortId).substring(prefix.length)
    if (/^\d{1,15}$/.test(rest)) lastTaskNum = Math.max(lastTaskNum, Number(rest))
}

const skipped = ['WstIntakeToken', 'WstIntakePlusTag', 'WstDocsWikiSpace']
for (const row of ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', baseWorkEffortId).list()) {
    if (skipped.includes(row.settingTypeEnumId) || row.settingValue == null || row.settingValue === '') continue
    ec.service.sync().name('store#mantle.work.effort.WorkEffortSetting').parameters({workEffortId: workEffortId,
        settingTypeEnumId: row.settingTypeEnumId, settingValue: row.settingValue}).call()
}
const base = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', baseWorkEffortId).one()
if (base?.isTemplate === 'Y' && isTemplate !== 'Y') ec.service.sync().name('create#mantle.work.effort.WorkEffortAssoc')
        .parameters({workEffortId: workEffortId, toWorkEffortId: baseWorkEffortId, workEffortAssocTypeEnumId: 'WeatBasedOn',
            fromDate: ec.user.nowTimestamp}).call()

const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const seqName = 'Project_' + workEffortId
    if (ec.entity.find('moqui.entity.SequenceValueItem').condition('seqName', seqName).one() == null)
        ec.service.sync().name('create#moqui.entity.SequenceValueItem').parameters({seqName: seqName, seqNum: lastTaskNum || 0}).call()
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

isClient = false; userPartyId = null
clientProjectIds = []; clientOrgIds = []; clientPartyIds = []; clientContactPartyIds = []
shareHoursProjectIds = []; shareRepositoryProjectIds = []; statusUpdateIds = []; scopePartyIds = []
const forUserId = userId || ec.user.userId
if (!forUserId) return
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const now = ec.user.nowTimestamp
    const cf = ec.entity.conditionFactory
    const current = (from, thru) => cf.makeConditionDate(from || 'fromDate', thru || 'thruDate', null)
    if (forUserId === ec.user.userId) {
        isClient = ec.user.hasPermission('PROJECT_CLIENT')
    } else {
        const groupIds = Array.from(ec.entity.find('moqui.security.UserPermissionCheck').condition('userId', forUserId)
                .condition('userPermissionId', 'PROJECT_CLIENT').condition(current('groupFromDate', 'groupThruDate'))
                .condition(current('permissionFromDate', 'permissionThruDate')).list()).map((row) => row.userGroupId)
        isClient = groupIds.length > 0
    }
    if (!isClient) return
    const account = forUserId === ec.user.userId ? ec.user.userAccount
            : ec.entity.find('moqui.security.UserAccount').condition('userId', forUserId).one()
    userPartyId = account?.partyId || null
    if (!userPartyId) return
    const contactTypes = ['PrtContact', 'PrtEmployee', 'PrtRepresentative']
    const clientRoles = ['Customer', 'CustomerBillTo', 'ClientManager', 'ClientBilling']
    const relatedOrgIds = Array.from(new Set(Array.from(ec.entity.find('mantle.party.PartyRelationship')
            .condition('fromPartyId', userPartyId).condition('relationshipTypeEnumId', 'in', contactTypes)
            .condition(current()).list()).map((row) => row.toPartyId).filter((id) => id && id !== userPartyId)))
    const candidates = [userPartyId].concat(relatedOrgIds)
    const projects = new Set()
    const orgs = new Set()
    const roleRows = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('partyId', 'in', candidates)
            .condition('roleTypeId', 'in', clientRoles).condition('workEffortTypeEnumId', 'WetProject')
            .condition(cf.makeCondition('isTemplate', 'not-equals', 'Y', true)).condition(current())
            .selectField('workEffortId').selectField('partyId').list())
    const roleProjectIds = Array.from(new Set(roleRows.map((row) => row.workEffortId)))
    const signIn = roleProjectIds.length ? new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortSetting')
            .condition('workEffortId', 'in', roleProjectIds).condition('settingTypeEnumId', 'WstClientSignIn')
            .condition('settingValue', 'Y').list()).map((row) => row.workEffortId)) : new Set()
    for (const row of roleRows) {
        if (!signIn.has(row.workEffortId)) continue
        projects.add(row.workEffortId)
        if (row.partyId !== userPartyId) orgs.add(row.partyId)
    }
    clientProjectIds = Array.from(projects).sort()
    clientOrgIds = Array.from(orgs).sort()
    clientPartyIds = [userPartyId].concat(clientOrgIds)
    const contacts = new Set([userPartyId])
    if (clientOrgIds.length) for (const row of ec.entity.find('mantle.party.PartyRelationship').condition('toPartyId', 'in', clientOrgIds)
            .condition('relationshipTypeEnumId', 'in', contactTypes).condition(current()).selectField('fromPartyId').list())
        contacts.add(row.fromPartyId)
    clientContactPartyIds = Array.from(contacts).sort()
    const scope = new Set(clientContactPartyIds.concat(clientOrgIds))
    scopePartyIds = Array.from(scope).sort()
    if (!clientProjectIds.length) return
    for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', clientProjectIds)
            .selectField('ownerPartyId').list()) if (row.ownerPartyId) scope.add(row.ownerPartyId)
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('workEffortId', 'in', clientProjectIds)
            .condition(current()).selectField('partyId').list()) scope.add(row.partyId)
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('rootWorkEffortId', 'in', clientProjectIds)
            .condition('workEffortTypeEnumId', 'WetTask').condition('visibilityEnumId', 'in', ['WevAllUsers', 'WevGeneral'])
            .condition(current()).selectField('partyId').limit(5000).list()) scope.add(row.partyId)
    const requestIds = Array.from(ec.entity.find('mantle.request.Request').condition('rootWorkEffortId', 'in', clientProjectIds)
            .selectField('requestId').limit(5000).list()).map((row) => row.requestId)
    if (requestIds.length) for (const row of ec.entity.find('mantle.request.RequestParty').condition('requestId', 'in', requestIds)
            .selectField('partyId').list()) scope.add(row.partyId)
    scopePartyIds = Array.from(scope).sort()
    for (const projectId of clientProjectIds) {
        const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings')
                .parameter('workEffortId', projectId).call()?.settings || {}
        if (settings.WstShareHours === 'Y') shareHoursProjectIds.push(projectId)
        if (settings.WstShareRepositories === 'Y') shareRepositoryProjectIds.push(projectId)
    }
    statusUpdateIds = Array.from(new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortUpdate')
            .condition('workEffortId', 'in', clientProjectIds).condition('clientVisible', 'Y')
            .selectField('communicationEventId').list()).map((row) => row.communicationEventId))).sort()
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

const none = ['_NA_']
const list = (ids) => ids && ids.length ? Array.from(ids) : none
let info = null
ec.message.pushErrors()
try {
    info = ec.service.sync().name('mantle.work.ProjectServices.get#ClientProjectInfo').call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
} catch (err) {
    ec.logger.error(`Client project info of user ${ec.user.userId} not read, the client filters see nothing: ${err}`)
    info = {isClient: true}
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
clientUser = !!info.isClient
ec.user.context.clientUser = clientUser
ec.user.context.clientProjectIds = list(info.clientProjectIds)
ec.user.context.clientOrgIds = list(info.clientOrgIds)
ec.user.context.clientPartyIds = list(info.clientPartyIds)
ec.user.context.clientContactPartyIds = list(info.clientContactPartyIds)
ec.user.context.clientShareHoursProjectIds = list(info.shareHoursProjectIds)
ec.user.context.clientStatusUpdateIds = list(info.statusUpdateIds)
ec.user.context.clientScopePartyIds = list(info.scopePartyIds)

allProjects = false
isClient = false
itemVisibilityIds = null
userPartyId = ec.user.userAccount?.partyId || null
orgIds = []
visibleProjectIds = []
memberProjectIds = []
managedProjectIds = []
restrictedItemIds = []
// a client contact first: its client projects and their shared items only (strict: a failure sees nothing)
if (ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')) {
    isClient = true
    itemVisibilityIds = ['WevAllUsers', 'WevGeneral']
    ec.message.pushErrors()
    try {
        const client = ec.service.sync().name('mantle.work.ProjectServices.get#ClientProjectInfo').call() || {}
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        visibleProjectIds = Array.from(client.clientProjectIds || [])
    } catch (err) {
        ec.logger.error(`Visible projects of client user ${ec.user.userId} not read, none seen: ${err}`)
        visibleProjectIds = []
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    return
}
allProjects = !!ec.user.userId && ec.user.isInGroup('ADMIN')
if (!userPartyId) return
const shared = ['WevAllUsers', 'WevGeneral']
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const orgInfo = ec.service.sync().name('mantle.party.PartyServices.get#PartyOrganizationInfo').parameters({partyId: userPartyId}).call()
    orgIds = Array.from(orgInfo?.filterOrgIds || [])
    const visible = new Set()
    const managed = new Set()
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('partyId', userPartyId)
            .condition('workEffortTypeEnumId', 'WetProject').conditionDate('fromDate', 'thruDate', null)
            .selectField('workEffortId').selectField('roleTypeId').list()) {
        if (!memberProjectIds.includes(row.workEffortId)) memberProjectIds.push(row.workEffortId)
        visible.add(row.workEffortId)
        if (row.roleTypeId === 'ProjectManager' || row.roleTypeId === 'Manager') managed.add(row.workEffortId)
    }
    if (orgIds.length) {
        for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('ownerPartyId', 'in', orgIds)
                .condition('workEffortTypeEnumId', 'WetProject').condition('visibilityEnumId', 'in', shared)
                .selectField('workEffortId').list()) visible.add(row.workEffortId)
        for (const row of ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('partyId', 'in', orgIds)
                .condition('workEffortTypeEnumId', 'WetProject').condition('visibilityEnumId', 'in', shared)
                .conditionDate('fromDate', 'thruDate', null).selectField('workEffortId').list()) visible.add(row.workEffortId)
    }
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('partyId', userPartyId)
            .condition('workEffortTypeEnumId', 'WetTask').condition('visibilityEnumId', 'in', ['WevRestricted', 'WevConfidential'])
            .conditionDate('fromDate', 'thruDate', null).selectField('workEffortId').list()) {
        if (!restrictedItemIds.includes(row.workEffortId)) restrictedItemIds.push(row.workEffortId)
    }
    visibleProjectIds = Array.from(visible).sort()
    managedProjectIds = Array.from(managed).sort()
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

settings = {}
settingSources = {}
for (const row of ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', workEffortId).list()) {
    if (row.settingValue == null || row.settingValue === '') continue
    settings[row.settingTypeEnumId] = row.settingValue
    settingSources[row.settingTypeEnumId] = 'project'
}
if (!organizationPartyId) {
    const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    if (project?.ownerPartyId && ec.entity.find('mantle.party.Party').condition('partyId', project.ownerPartyId)
            .one()?.partyTypeEnumId === 'PtyOrganization') organizationPartyId = project.ownerPartyId
    if (!organizationPartyId) organizationPartyId = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty')
            .condition('workEffortId', workEffortId).condition('roleTypeId', 'Vendor').conditionDate('fromDate', 'thruDate', null)
            .orderBy('fromDate').list())[0]?.partyId || null
}
if (!organizationPartyId) return
const types = Array.from(ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'WorkEffortSettingType').useCache(true).list())
        .filter((type) => type.optionValue && settings[type.enumId] === undefined)
if (!types.length) return
const appSettings = {}
for (const row of ec.entity.find('mantle.party.PartySetting').condition('partyId', organizationPartyId)
        .condition('partySettingTypeId', 'in', Array.from(new Set(types.map((type) => type.optionValue)))).list()) {
    if (!row.settingValue) continue
    try {
        const parsed = JSON.parse(row.settingValue)
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) appSettings[row.partySettingTypeId] = parsed
        else ec.logger.error(`Project settings of ${workEffortId}: the ${row.partySettingTypeId} setting of ${organizationPartyId} is not a JSON object, skipped`)
    } catch (err) {
        ec.logger.error(`Project settings of ${workEffortId}: the ${row.partySettingTypeId} setting of ${organizationPartyId} is not JSON, skipped: ${err}`)
    }
}
for (const type of types) {
    const value = appSettings[type.optionValue]?.[type.enumCode || type.enumId]
    if (value == null || value === '') continue
    settings[type.enumId] = typeof value === 'boolean' ? (value ? 'Y' : 'N') : typeof value === 'string' ? value : JSON.stringify(value)
    settingSources[type.enumId] = 'organization'
}

const D = (value) => toDecimal(value ?? 0)
const hundred = toDecimal(100)
const zero = toDecimal(0)
const we = workEffort
const actualClientCost = D(we.actualClientCost)
const totalClientCostAllowed = D(we.totalClientCostAllowed)
const remainingWorkTime = D(we.remainingWorkTime)
const actualWorkTime = D(we.actualWorkTime)
const totalTimeAllowed = D(we.totalTimeAllowed)
const hasEstimate = we.estimatedWorkTime != null && !D(we.estimatedWorkTime).isZero()

actualProfit = actualClientCost.subtract(D(we.actualCost))
clientBudgetRemaining = totalClientCostAllowed.subtract(actualClientCost)
clientBudgetUsedPercent = totalClientCostAllowed.isZero() ? zero : actualClientCost.divide(totalClientCostAllowed).multiply(hundred)
clientActualOverBudget = actualClientCost.compare(totalClientCostAllowed) > 0 && !totalClientCostAllowed.isZero()

actualPlusRemainingTime = actualWorkTime.add(remainingWorkTime)
bestTimeEstimate = (we.estimatedWorkTime == null || actualPlusRemainingTime.compare(we.estimatedWorkTime) > 0) ? actualPlusRemainingTime : we.estimatedWorkTime
estimatedCompletePercent = hasEstimate ? actualWorkTime.divide(we.estimatedWorkTime).multiply(hundred) : zero
estimatedRemainingPercent = hasEstimate ? remainingWorkTime.divide(we.estimatedWorkTime).multiply(hundred) : zero
estimatedActualPlusRemainingDiff = D(we.estimatedWorkTime).subtract(actualPlusRemainingTime)
// over the estimate only when there is one: time on a project with no estimate is not a warning (impl-projects.md F70)
actualPlusRemainingOverEstimated = hasEstimate && actualPlusRemainingTime.compare(D(we.estimatedWorkTime)) > 0

timeBudgetCompletePercent = totalTimeAllowed.isZero() ? zero : actualWorkTime.divide(totalTimeAllowed).multiply(hundred)
timeBudgetRemainingPercent = totalTimeAllowed.isZero() ? zero : remainingWorkTime.divide(totalTimeAllowed).multiply(hundred)
timeBudgetActualPlusRemainingDiff = totalTimeAllowed.subtract(actualPlusRemainingTime)
actualPlusRemainingOverTimeBudget = actualPlusRemainingTime.compare(totalTimeAllowed) > 0

clientAverageHourCost = actualWorkTime.isZero() ? zero : actualClientCost.divide(actualWorkTime)
clientEstimatedCost = clientAverageHourCost.multiply(bestTimeEstimate)
clientBudgetEstimateDiff = totalClientCostAllowed.subtract(clientEstimatedCost)

estimatedCompleteBudgetPercentGap = estimatedCompletePercent.subtract(clientBudgetUsedPercent)
estimatedCompleteOverBudget = estimatedCompletePercent.compare(clientBudgetUsedPercent) < 0

projectDanger = clientActualOverBudget || actualPlusRemainingOverEstimated
projectWarning = estimatedCompleteOverBudget

if.script:
const msSummary = msSummaryList[0]
for (const statsField of statsFields) milestoneStats[statsField] = toDecimal(msSummary[statsField] ?? 0)
milestoneStatsList.push(milestoneStats)

// add current values to stats totals
for (const statsField of statsFields) milestoneStatsTotals[statsField] = milestoneStatsTotals[statsField].add(milestoneStats[statsField])

actions.script:
// derived values, for each milestone and then for the totals Map added to the end of the list
const perDay = toDecimal(timePerDay)
const zero = toDecimal(0)
const hundred = toDecimal(100)
const derive = (stats) => {
    const est = stats.estimatedWorkTime
    const hasEst = !est.isZero()
    stats.estimatedWorkDays = est.divide(perDay)
    stats.remainingWorkDays = stats.remainingWorkTime.divide(perDay)
    stats.actualWorkDays = stats.actualWorkTime.divide(perDay)
    stats.totalTimeAllowedDays = stats.totalTimeAllowed.divide(perDay)
    stats.workTimePercentComplete = hasEst ? est.subtract(stats.remainingWorkTime).divide(est).multiply(hundred) : zero
    stats.workRemainingPercent = hasEst ? stats.remainingWorkTime.divide(est).multiply(hundred) : zero
    stats.workActualPercent = hasEst ? stats.actualWorkTime.divide(est).multiply(hundred) : zero
    stats.workActRemPercent = hasEst ? stats.actualWorkTime.add(stats.remainingWorkTime).divide(est).multiply(hundred) : zero
}
for (const stats of milestoneStatsList) derive(stats)
derive(milestoneStatsTotals)
milestoneStatsList.push(milestoneStatsTotals)

workItemList = []
totals = {totalEstimatedWorkTime: 0, totalRemainingWorkTime: 0, totalActualWorkTime: 0, totalBudget: 0, totalEstimatedPoints: 0,
    itemCount: 0, doneCount: 0, percentDone: null}
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const all = !!vis.allProjects
const visible = new Set(Array.from(vis.visibleProjectIds || []))
const managed = new Set(Array.from(vis.managedProjectIds || []))
const restricted = new Set(Array.from(vis.restrictedItemIds || []))
const me = vis.userPartyId || null
const fields = ['workEffortId', 'workEffortName', 'parentWorkEffortId', 'rootWorkEffortId', 'workEffortTypeEnumId', 'statusId', 'purposeEnumId',
    'priority', 'sequenceNum', 'visibilityEnumId', 'ownerPartyId', 'estimatedWorkTime', 'remainingWorkTime', 'actualWorkTime', 'totalTimeAllowed',
    'estimatedPoints', 'estimatedStartDate', 'estimatedCompletionDate', 'resolutionEnumId']
const num = (value) => value == null || value === '' ? 0 : Number(String(value))
const rankOf = (row) => row.sequenceNum == null || row.sequenceNum === '' ? null : Number(String(row.sequenceNum))
const numberOf = (id) => { const match = /(\d+)$/.exec(String(id)); return match ? Number(match[1]) : Number.MAX_SAFE_INTEGER }
const byRank = (left, right) => {
    const l = rankOf(left), r = rankOf(right)
    if (l != null && r != null && l !== r) return l - r
    if (l != null && r == null) return -1
    if (l == null && r != null) return 1
    return numberOf(left.workEffortId) - numberOf(right.workEffortId) || String(left.workEffortId).localeCompare(String(right.workEffortId))
}
const plain = (row) => { const out = {}; for (const name of fields) out[name] = row[name] ?? null; return out }
// the items of no project the user is on: owner or a current party
const myLooseIds = new Set()
const seen = (row) => {
    if (all) return true
    if (!row.rootWorkEffortId) return (!!me && row.ownerPartyId === me) || myLooseIds.has(row.workEffortId)
    if (!visible.has(row.rootWorkEffortId)) return false
    // a client sees the items shared with it only (impl-projects.md P10)
    if (vis.itemVisibilityIds && !Array.from(vis.itemVisibilityIds).includes(row.visibilityEnumId)) return false
    if (['WevRestricted', 'WevConfidential'].includes(row.visibilityEnumId))
        return managed.has(row.rootWorkEffortId) || restricted.has(row.workEffortId)
    return true
}
const find = () => ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetTask')

// the items of each project, read once: by id and by parent
const universes = new Map()
const universeOf = (root) => {
    if (universes.has(root)) return universes.get(root)
    const byId = new Map()
    const kids = new Map()
    let rows
    if (root) rows = Array.from(find().condition('rootWorkEffortId', root).list()).map(plain)
    else rows = []
    for (const row of rows) {
        if (!seen(row)) continue
        byId.set(row.workEffortId, row)
    }
    for (const row of byId.values()) {
        const parent = row.parentWorkEffortId || ''
        if (!kids.has(parent)) kids.set(parent, [])
        kids.get(parent).push(row)
    }
    const universe = {byId, kids, rollups: new Map()}
    universes.set(root, universe)
    return universe
}
// an item of no project: its subtree by parent, a level at a time
const looseKids = new Map()
const looseKidsOf = (id) => {
    if (!looseKids.has(id)) looseKids.set(id, Array.from(find().condition('parentWorkEffortId', id).list()).map(plain).filter(seen))
    return looseKids.get(id)
}
const childrenOf = (row) => row.rootWorkEffortId ? (universeOf(row.rootWorkEffortId).kids.get(row.workEffortId) || []) : looseKidsOf(row.workEffortId)
const looseRollups = new Map()
const rollupOf = (row, depth) => {
    const cache = row.rootWorkEffortId ? universeOf(row.rootWorkEffortId).rollups : looseRollups
    if (cache.has(row.workEffortId)) return cache.get(row.workEffortId)
    const sum = {estimated: num(row.estimatedWorkTime), remaining: num(row.remainingWorkTime), actual: num(row.actualWorkTime),
        budget: num(row.totalTimeAllowed), points: num(row.estimatedPoints), items: 0, done: 0}
    if ((depth || 0) < 200) for (const child of childrenOf(row)) {
        if (child.statusId === 'WeCancelled') continue
        const under = rollupOf(child, (depth || 0) + 1)
        sum.estimated += under.estimated; sum.remaining += under.remaining; sum.actual += under.actual
        sum.budget += under.budget; sum.points += under.points
        sum.items += 1 + under.items
        sum.done += (['WeComplete', 'WeClosed'].includes(child.statusId) ? 1 : 0) + under.done
    }
    cache.set(row.workEffortId, sum)
    return sum
}
const round = (value) => Math.round(value * 100) / 100
const decorate = (row, depth) => {
    const sum = rollupOf(row)
    return Object.assign({}, row, {childCount: childrenOf(row).length, hasChildren: childrenOf(row).length > 0, depth: depth,
        totalEstimatedWorkTime: round(sum.estimated), totalRemainingWorkTime: round(sum.remaining), totalActualWorkTime: round(sum.actual),
        totalBudget: round(sum.budget), totalEstimatedPoints: round(sum.points), itemCount: sum.items, doneCount: sum.done,
        percentDone: sum.estimated > 0 ? Math.max(0, Math.min(100, Math.round((sum.estimated - sum.remaining) / sum.estimated * 100))) : null})
}
const depthOf = (row) => {
    let depth = 0
    let at = row
    const byId = row.rootWorkEffortId ? universeOf(row.rootWorkEffortId).byId : null
    for (let guard = 0; at && at.parentWorkEffortId && guard < 500; guard++) {
        at = byId ? byId.get(at.parentWorkEffortId) : find().condition('workEffortId', at.parentWorkEffortId).one()
        depth++
    }
    return depth
}
const statusIds = statusId ? String(statusId).split(',').map((id) => id.trim()).filter((id) => id) : []
const statusOk = (row) => !statusIds.length || statusIds.includes(row.statusId)
if (me && !all) for (const wep of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('partyId', me)
        .conditionDate('fromDate', 'thruDate', null).selectField('workEffortId').list()) myLooseIds.add(wep.workEffortId)

let rows = []
const added = new Set()
if (parentWorkEffortId) {
    const parent = find().condition('workEffortId', parentWorkEffortId).one()
    if (parent == null || !seen(parent)) return
    const parentRow = plain(parent)
    const depth = depthOf(parentRow) + 1
    rows = childrenOf(parentRow).filter(statusOk).sort(byRank).map((row) => decorate(row, depth))
} else if (topLevel && rootWorkEffortId) {
    if (!all && !visible.has(rootWorkEffortId)) return
    rows = (universeOf(rootWorkEffortId).kids.get('') || []).filter(statusOk).sort(byRank).map((row) => decorate(row, 0))
} else if (workEffortIds) {
    const ids = (typeof workEffortIds === 'string' ? workEffortIds.split(',') : Array.from(workEffortIds)).map((id) => String(id).trim()).filter((id) => id)
    if (!ids.length) return
    const found = Array.from(find().condition('workEffortId', 'in', ids).list()).map(plain).filter(seen)
    const wanted = []
    for (const row of found) {
        const fromUniverse = row.rootWorkEffortId ? universeOf(row.rootWorkEffortId).byId.get(row.workEffortId) || row : row
        wanted.push(fromUniverse)
    }
    const ancestors = []
    if (withAncestors) {
        for (const row of wanted) {
            const chain = []
            let at = row
            const byId = row.rootWorkEffortId ? universeOf(row.rootWorkEffortId).byId : null
            for (let guard = 0; at && at.parentWorkEffortId && guard < 500; guard++) {
                at = byId ? byId.get(at.parentWorkEffortId) : (() => { const one = find().condition('workEffortId', at.parentWorkEffortId).one(); return one && seen(one) ? plain(one) : null })()
                if (at) chain.unshift(at)
            }
            for (const ancestor of chain) if (!added.has(ancestor.workEffortId) && !ids.includes(ancestor.workEffortId)) {
                added.add(ancestor.workEffortId)
                ancestors.push(ancestor)
            }
        }
    }
    const byOrder = new Map(ids.map((id, i) => [id, i]))
    wanted.sort((left, right) => byOrder.get(left.workEffortId) - byOrder.get(right.workEffortId))
    rows = ancestors.map((row) => decorate(row, depthOf(row))).concat(wanted.map((row) => decorate(row, depthOf(row))))
}
workItemList = rows
for (const row of rows) {
    if (added.has(row.workEffortId)) continue
    totals.totalEstimatedWorkTime += row.totalEstimatedWorkTime
    totals.totalRemainingWorkTime += row.totalRemainingWorkTime
    totals.totalActualWorkTime += row.totalActualWorkTime
    totals.totalBudget += row.totalBudget
    totals.totalEstimatedPoints += row.totalEstimatedPoints
    totals.itemCount += 1 + row.itemCount
    totals.doneCount += (['WeComplete', 'WeClosed'].includes(row.statusId) ? 1 : 0) + row.doneCount
}
for (const key of ['totalEstimatedWorkTime', 'totalRemainingWorkTime', 'totalActualWorkTime', 'totalBudget', 'totalEstimatedPoints'])
    totals[key] = round(totals[key])
totals.percentDone = totals.totalEstimatedWorkTime > 0 ? Math.max(0, Math.min(100, Math.round((totals.totalEstimatedWorkTime
        - totals.totalRemainingWorkTime) / totals.totalEstimatedWorkTime * 100))) : null

itemList = []
dependencyList = []
planItemList = []
const ids = workEffortIds == null ? [] : (typeof workEffortIds === 'string' ? workEffortIds.split(',') : Array.from(workEffortIds))
        .map((id) => String(id).trim()).filter((id) => id)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const dayOf = (value) => toMillis(value) == null ? null : ec.l10n.format(String(toMillis(value)), 'yyyy-MM-dd')
const doneStatus = (statusId) => ['WeComplete', 'WeClosed'].includes(statusId)
const rows = ids.length ? Array.from(ec.service.sync().name('mantle.work.ProjectServices.get#WorkItemTree').parameters({workEffortIds: ids,
    withAncestors: withAncestors}).call()?.workItemList || []) : []
const asked = new Set(ids)
const projectIds = new Set(rootWorkEffortId ? [rootWorkEffortId] : [])
for (const row of rows) if (row.rootWorkEffortId) projectIds.add(row.rootWorkEffortId)

// the spans of the subtrees: one read of each project's items
const kids = new Map()
const dates = new Map()
for (const projectId of projectIds) {
    for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', projectId).condition('workEffortTypeEnumId', 'WetTask')
            .selectField('workEffortId,parentWorkEffortId,statusId,estimatedStartDate,estimatedCompletionDate').list()) {
        if (row.statusId === 'WeCancelled') continue
        dates.set(row.workEffortId, [dayOf(row.estimatedStartDate), dayOf(row.estimatedCompletionDate)])
        if (row.parentWorkEffortId) {
            if (!kids.has(row.parentWorkEffortId)) kids.set(row.parentWorkEffortId, [])
            kids.get(row.parentWorkEffortId).push(row.workEffortId)
        }
    }
}
const spans = new Map()
const spanOf = (id, depth) => {
    if (spans.has(id)) return spans.get(id)
    const own = dates.get(id) || [null, null]
    let first = own[0] || own[1]
    let last = own[1] || own[0]
    if ((depth || 0) < 200) for (const child of kids.get(id) || []) {
        const [childFirst, childLast] = spanOf(child, (depth || 0) + 1)
        if (childFirst && (!first || childFirst < first)) first = childFirst
        if (childLast && (!last || childLast > last)) last = childLast
    }
    const span = [first || null, last || null]
    spans.set(id, span)
    return span
}
// the plan items each item is in now
const plans = {}
const rowIds = rows.map((row) => row.workEffortId)
for (let i = 0; i < rowIds.length; i += 500) for (const assoc of ec.entity.find('mantle.work.effort.WorkEffortAssoc')
        .condition('toWorkEffortId', 'in', rowIds.slice(i, i + 500)).condition('workEffortAssocTypeEnumId', 'in', ['WeatMilestone', 'WeatRelease', 'WeatSprint', 'WeatComponent'])
        .conditionDate('fromDate', 'thruDate', null).selectField('workEffortId,toWorkEffortId,workEffortAssocTypeEnumId').list()) {
    (plans[assoc.toWorkEffortId] || (plans[assoc.toWorkEffortId] = {}))[assoc.workEffortAssocTypeEnumId] = assoc.workEffortId
}
for (const row of rows) {
    const isDone = doneStatus(row.statusId)
    const span = spanOf(row.workEffortId)
    let progress = isDone ? 100 : (row.percentDone != null ? Number(row.percentDone) : null)
    if (progress == null) progress = row.itemCount ? Math.round(Number(row.doneCount || 0) * 100 / Number(row.itemCount)) : 0
    const plan = plans[row.workEffortId] || {}
    itemList.push(Object.assign({}, row, {ancestor: !asked.has(row.workEffortId), startDay: dayOf(row.estimatedStartDate), dueDay: dayOf(row.estimatedCompletionDate),
        spanStartDay: span[0], spanDueDay: span[1], progress: Math.max(0, Math.min(100, progress)), isDone: isDone,
        milestoneId: plan.WeatMilestone || null, releaseId: plan.WeatRelease || null, sprintId: plan.WeatSprint || null, componentId: plan.WeatComponent || null}))
}

// the dependencies between the items, and whether each is kept
const byId = new Map(itemList.map((row) => [row.workEffortId, row]))
const nextWeekday = (day, count) => {
    const d = new Date(day + 'T12:00:00Z')
    let left = count
    while (left > 0) { d.setUTCDate(d.getUTCDate() + 1); if (d.getUTCDay() !== 0 && d.getUTCDay() !== 6) left-- }
    return d.toISOString().substring(0, 10)
}
for (let i = 0; i < rowIds.length; i += 500) for (const link of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', 'in', rowIds.slice(i, i + 500))
        .condition('workEffortAssocTypeEnumId', 'WeatDependsOn').conditionDate('fromDate', 'thruDate', null).list()) {
    const dependent = byId.get(link.workEffortId)
    const predecessor = byId.get(link.toWorkEffortId)
    if (!dependent || !predecessor) continue
    const lag = link.lagDays == null ? 0 : Number(String(link.lagDays)) || 0
    const before = predecessor.dueDay || predecessor.startDay
    const after = dependent.startDay || dependent.dueDay
    const violated = !!before && !!after && !dependent.isDone && after < nextWeekday(before, 1 + Math.max(0, Math.ceil(lag)))
    dependencyList.push({workEffortId: link.workEffortId, toWorkEffortId: link.toWorkEffortId, lagDays: link.lagDays == null ? null : lag,
        fromDate: link.fromDate, violated: violated})
}

if (!includePlanItems || !projectIds.size) return
const kinds = {WetMilestone: 'milestone', WetRelease: 'release', WetSprint: 'sprint'}
const planRows = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', 'in', Array.from(projectIds))
        .condition('workEffortTypeEnumId', 'in', Object.keys(kinds)).condition('statusId', 'not-equals', 'WeCancelled').list())
const summary = planRows.length ? ec.service.sync().name('mantle.work.ProjectServices.get#PlanItemSummary')
        .parameters({workEffortIdList: planRows.map((row) => row.workEffortId)}).call()?.summaryMap || {} : {}
for (const row of planRows) {
    const stats = summary[row.workEffortId] || {}
    planItemList.push({workEffortId: row.workEffortId, kind: kinds[row.workEffortTypeEnumId], workEffortTypeEnumId: row.workEffortTypeEnumId,
        workEffortName: row.workEffortName || row.workEffortId, rootWorkEffortId: row.rootWorkEffortId, statusId: row.statusId,
        startDay: dayOf(row.estimatedStartDate), dueDay: dayOf(row.estimatedCompletionDate), actualCompletionDay: dayOf(row.actualCompletionDate),
        percentDone: stats.percentDone || 0, itemCount: stats.itemCount || 0, doneCount: stats.doneCount || 0})
}
planItemList.sort((left, right) => String(left.dueDay || left.startDay || '9999').localeCompare(String(right.dueDay || right.startDay || '9999'))
        || String(left.workEffortId).localeCompare(String(right.workEffortId)))

const zero = toDecimal(0)
const hundred = toDecimal(100)
const perDay = toDecimal(timePerDay)
const derive = (stats) => {
    const est = stats.estimatedWorkTime
    const budget = stats.totalTimeAllowed
    const hasEst = !est.isZero()
    const hasBudget = !budget.isZero()
    stats.estimatedWorkDays = est.divide(perDay)
    stats.remainingWorkDays = stats.remainingWorkTime.divide(perDay)
    stats.actualWorkDays = stats.actualWorkTime.divide(perDay)
    stats.totalTimeAllowedDays = budget.divide(perDay)

    stats.workTimePercentComplete = hasEst ? est.subtract(stats.remainingWorkTime).divide(est).multiply(hundred) : zero
    stats.workRemainingPercent = hasEst ? stats.remainingWorkTime.divide(est).multiply(hundred) : zero
    stats.workActualPercent = hasEst ? stats.actualWorkTime.divide(est).multiply(hundred) : zero
    stats.workActRemPercent = hasEst ? stats.actualWorkTime.add(stats.remainingWorkTime).divide(est).multiply(hundred) : zero

    stats.budgetTimePercentComplete = hasBudget ? budget.subtract(stats.remainingWorkTime).divide(budget).multiply(hundred) : zero
    stats.budgetRemainingPercent = hasBudget ? stats.remainingWorkTime.divide(budget).multiply(hundred) : zero
    stats.budgetActualPercent = hasBudget ? stats.actualWorkTime.divide(budget).multiply(hundred) : zero
    stats.budgetActRemPercent = hasBudget ? stats.actualWorkTime.add(stats.remainingWorkTime).divide(budget).multiply(hundred) : zero
}

// adds a work effort and all its descendants to stats
const addChildStats = (current, stats) => {
    if (current == null || current.statusId === "WeCancelled") return
    // add current values
    for (const statsField of statsFields) {
        if (current[statsField] != null && !toDecimal(current[statsField]).isZero()) stats[statsField] = stats[statsField].add(current[statsField])
    }

    // recurse for each child
    if (!withChildrenIdSet.includes(current.workEffortId)) return
    const childList = ec.entity.find("mantle.work.effort.WorkEffort")
            .condition("parentWorkEffortId", current.workEffortId).list()
    for (const child of childList) addChildStats(child, stats)
}

const childStatsTotals = {workEffortId: 'Total', workEffortName: '', priority: ''}
for (const statsField of statsFields) childStatsTotals[statsField] = zero

childStatsList = []
for (const directChild of directChildren) {
    const topLevelStats = {workEffortId: directChild.workEffortId, workEffortName: directChild.workEffortName,
            priority: directChild.priority}
    for (const statsField of statsFields) topLevelStats[statsField] = zero
    addChildStats(directChild, topLevelStats)

    // calc derived values
    derive(topLevelStats)

    // add current values to stats totals
    for (const statsField of statsFields) childStatsTotals[statsField] = childStatsTotals[statsField].add(topLevelStats[statsField])

    // all done, add to the list
    childStatsList.push(topLevelStats)
}

// add the totals Map to the end of the list
derive(childStatsTotals)
childStatsList.push(childStatsTotals)

then.script:
resultList = []
if (addOptional) resultList.push({partyId:"", name:"None"})
for (const party of partyList) resultList.push({partyId:party.partyId, name:ec.resource.expand('PartyNameTemplate', '', party)})

else.script:
let queryString = '(' + (term.includes('*') ? term : term.split(' ').map((word) => word + '* ').join('')) + ')'
if (roleTypeId) queryString += ' AND roles.roleTypeId:(' + roleTypeId.replace(/,/g, ' OR ') + ')'
queryString += ' AND (NOT disabled:Y)'
partySearch = {queryString: queryString, indexName: searchIndexName, documentType: searchPartyDocType}

// the org limit is a trusted filter, so it does not change scores and the user query cannot widen it
let ownerPartyIds = null
if ('MANTLE_USER_ORG' === entityFilterSetId) ownerPartyIds = (filterOrgIds || []).concat(['_NA_'])
else if ('MANTLE_ACTIVE_ORG' === entityFilterSetId && activeOrgId) ownerPartyIds = [activeOrgId, '_NA_']
// a personal contact (privateOwnerUserId) only for its owner, with or without an org filter
const notPrivate = {field: {name: 'privateOwnerUserId', op: 'exists', negate: true}}
const privateFilter = ec.user.userId ? {bool: {any: [notPrivate,
        {field: {name: 'privateOwnerUserId', op: 'eq', value: ec.user.userId}}]}} : notPrivate
partySearch.filter = ownerPartyIds != null ? {bool: {all: [{field: {name: 'ownerPartyId', op: 'in', values: ownerPartyIds}},
        privateFilter]}} : privateFilter

actions.script:
const infix = {WetMilestone: 'MS', WetRelease: 'REL', WetComponent: 'CMP'}[workEffortTypeEnumId]
if (!infix) { ec.message.addError(ec.resource.expand('${workEffortTypeEnumId} is not a kind of plan item', '', {workEffortTypeEnumId})); return }
const pattern = new RegExp('-' + infix + '-(\\d+)$')
let highest = 0
for (const row of Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', rootWorkEffortId)
        .condition('workEffortTypeEnumId', workEffortTypeEnumId).selectField('workEffortId').list())) {
    const match = pattern.exec(String(row.workEffortId))
    if (match) highest = Math.max(highest, Number(match[1]))
}
number = highest + 1
while (ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', rootWorkEffortId + '-' + infix + '-' + number).count() > 0) number++
workEffortId = rootWorkEffortId + '-' + infix + '-' + number

const kinds = {WetMilestone: 'milestone', WetRelease: 'release', WetComponent: 'component'}
if (!kinds[workEffortTypeEnumId]) { ec.message.addError(ec.resource.expand('${workEffortTypeEnumId} is not a kind of plan item', '', {workEffortTypeEnumId})); return }
const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', rootWorkEffortId).one()
if (project == null || project.workEffortTypeEnumId !== 'WetProject') { ec.message.addError(ec.resource.expand('Project ${rootWorkEffortId} not found', '', {rootWorkEffortId})); return }
const name = String(workEffortName || '').trim()
if (!name) { ec.message.addError(ec.l10n.localize(workEffortTypeEnumId === 'WetRelease' ? 'A release needs its version' : 'A plan item needs a name')); return }
if (workEffortTypeEnumId === 'WetRelease' && ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', rootWorkEffortId)
        .condition('workEffortTypeEnumId', 'WetRelease').condition('workEffortName', name).count() > 0) {
    ec.message.addError(ec.resource.expand('The project has a release ${name} already', '', {name})); return
}
const millis = (value) => value == null || value === '' ? null : (/^-?\d+$/.test(String(value)) ? Number(String(value)) : Date.parse(String(value)))
if (estimatedStartDate != null && estimatedCompletionDate != null && millis(estimatedCompletionDate) < millis(estimatedStartDate)) {
    ec.message.addError(ec.l10n.localize('The due date is not before the start')); return
}
let id = String(workEffortId || '').trim()
if (id) {
    if (ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).count() > 0) {
        ec.message.addError(ec.resource.expand('The id ${id} is taken', '', {id})); return
    }
} else {
    id = ec.service.sync().name('mantle.work.ProjectServices.get#PlanItemDefaults').parameters({rootWorkEffortId: rootWorkEffortId,
        workEffortTypeEnumId: workEffortTypeEnumId}).call()?.workEffortId
    if (ec.message.hasError()) return
}
workEffortId = ec.service.sync().name('create#mantle.work.effort.WorkEffort').parameters({workEffortId: id, workEffortTypeEnumId: workEffortTypeEnumId,
    rootWorkEffortId: rootWorkEffortId, workEffortName: name, description: description || null, statusId: statusId || 'WeInPlanning',
    estimatedStartDate: estimatedStartDate || null, estimatedCompletionDate: estimatedCompletionDate || null, timeUomId: 'TF_hr'}).call()?.workEffortId || id

service-call.in-map:
{rootWorkEffortId:rootWorkEffortId,
                    workEffortTypeEnumId:'WetMilestone', workEffortId:workEffortId, workEffortName:workEffortName, description:description,
                    estimatedStartDate:estimatedStartDate, estimatedCompletionDate:estimatedCompletionDate, statusId:statusId}

{rootWorkEffortId:rootWorkEffortId,
                    workEffortTypeEnumId:'WetRelease', workEffortId:workEffortId, workEffortName:workEffortName, description:description,
                    estimatedStartDate:estimatedStartDate, estimatedCompletionDate:estimatedCompletionDate, statusId:statusId}

actions.script:
const plan = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (plan == null || !['WetMilestone', 'WetRelease', 'WetComponent'].includes(plan.workEffortTypeEnumId)) {
    ec.message.addError(ec.resource.expand('Plan item ${workEffortId} not found', '', {workEffortId})); return
}
const fields = {workEffortId: workEffortId}
if (workEffortName != null) {
    const name = String(workEffortName).trim()
    if (!name) { ec.message.addError(ec.l10n.localize(plan.workEffortTypeEnumId === 'WetRelease' ? 'A release needs its version' : 'A plan item needs a name')); return }
    if (plan.workEffortTypeEnumId === 'WetRelease' && name !== plan.workEffortName && ec.entity.find('mantle.work.effort.WorkEffort')
            .condition('rootWorkEffortId', plan.rootWorkEffortId).condition('workEffortTypeEnumId', 'WetRelease').condition('workEffortName', name)
            .condition('workEffortId', 'not-equals', workEffortId).count() > 0) {
        ec.message.addError(ec.resource.expand('The project has a release ${name} already', '', {name})); return
    }
    fields.workEffortName = name
}
if (description != null) fields.description = String(description)
if (estimatedStartDate != null) fields.estimatedStartDate = estimatedStartDate
if (estimatedCompletionDate != null) fields.estimatedCompletionDate = estimatedCompletionDate
const clear = (clearFields == null || clearFields === '' ? [] : typeof clearFields === 'string' ? clearFields.split(',') : Array.from(clearFields))
        .map((name) => String(name).trim())
for (const name of clear) if (['description', 'estimatedStartDate', 'estimatedCompletionDate'].includes(name)) fields[name] = null
const millis = (value) => value == null || value === '' ? null : (/^-?\d+$/.test(String(value)) ? Number(String(value)) : Date.parse(String(value)))
const start = millis('estimatedStartDate' in fields ? fields.estimatedStartDate : plan.estimatedStartDate)
const end = millis('estimatedCompletionDate' in fields ? fields.estimatedCompletionDate : plan.estimatedCompletionDate)
if (start != null && end != null && !Number.isNaN(start) && !Number.isNaN(end) && end < start) { ec.message.addError(ec.l10n.localize('The due date is not before the start')); return }
if (statusId && statusId !== plan.statusId) {
    // a gated milestone is reached only by its approval (approve#MilestoneApproval)
    if (plan.workEffortTypeEnumId === 'WetMilestone' && ['WeComplete', 'WeClosed'].includes(statusId) && !['WeComplete', 'WeClosed'].includes(plan.statusId)
            && ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', workEffortId).condition('settingTypeEnumId', 'WstApprovalRequired')
                .disableAuthz().one()?.settingValue === 'Y') {
        const latest = Array.from(ec.entity.find('mantle.work.effort.WorkEffortApproval').condition('workEffortId', workEffortId)
                .orderBy('-requestedDate').orderBy('-workEffortApprovalId').limit(1).disableAuthz().list())[0]
        if (latest?.statusId !== 'WeaApproved') {
            ec.message.addError(ec.resource.expand('${name} needs approval before it is reached: ask for it', '', {name: plan.workEffortName || workEffortId})); return }
    }
    fields.statusId = statusId
    if (['WeComplete', 'WeClosed'].includes(statusId) && plan.actualCompletionDate == null) fields.actualCompletionDate = ec.user.nowTimestamp
    if (['WeInPlanning', 'WeApproved', 'WeInProgress'].includes(statusId) && plan.actualCompletionDate != null) fields.actualCompletionDate = null
}
if (Object.keys(fields).length > 1) ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters(fields).call()

summaryMap = {}
const ids = Array.from(new Set(Array.from(workEffortIdList || []).map(String).filter((id) => id)))
if (!ids.length) return
const number = (value) => value == null || value === '' ? 0 : Number(String(value)) || 0
for (const id of ids) summaryMap[id] = {itemCount: 0, doneCount: 0, inProgressCount: 0, notStartedCount: 0, cancelledCount: 0, percentDone: 0,
    estimatedWorkTime: 0, remainingWorkTime: 0, actualWorkTime: 0, hoursPercent: 0, estimatedPoints: 0, donePoints: 0}
const assocs = []
for (let i = 0; i < ids.length; i += 500) assocs.push(...Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc')
        .condition('workEffortId', 'in', ids.slice(i, i + 500)).condition('workEffortAssocTypeEnumId', 'in', ['WeatMilestone', 'WeatRelease', 'WeatSprint', 'WeatComponent'])
        .conditionDate('fromDate', 'thruDate', null).selectField('workEffortId,toWorkEffortId').list()))
const itemIds = Array.from(new Set(assocs.map((assoc) => assoc.toWorkEffortId)))
const items = {}
for (let i = 0; i < itemIds.length; i += 500) for (const row of Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', itemIds.slice(i, i + 500))
        .selectField('workEffortId,statusId,estimatedWorkTime,remainingWorkTime,actualWorkTime,estimatedPoints').list())) items[row.workEffortId] = row
const seen = new Set()
for (const assoc of assocs) {
    const key = assoc.workEffortId + '|' + assoc.toWorkEffortId
    const item = items[assoc.toWorkEffortId]
    if (seen.has(key) || item == null) continue
    seen.add(key)
    const summary = summaryMap[assoc.workEffortId]
    if (item.statusId === 'WeCancelled') { summary.cancelledCount++; continue }
    summary.itemCount++
    const done = ['WeComplete', 'WeClosed'].includes(item.statusId)
    if (done) summary.doneCount++
    else if (['WeInPlanning', 'WeApproved'].includes(item.statusId)) summary.notStartedCount++
    else summary.inProgressCount++
    summary.estimatedWorkTime += number(item.estimatedWorkTime)
    summary.remainingWorkTime += number(done ? 0 : item.remainingWorkTime)
    summary.actualWorkTime += number(item.actualWorkTime)
    summary.estimatedPoints += number(item.estimatedPoints)
    if (done) summary.donePoints += number(item.estimatedPoints)
}
for (const summary of Object.values(summaryMap)) {
    summary.percentDone = summary.itemCount ? Math.round(summary.doneCount * 100 / summary.itemCount) : 0
    const est = summary.estimatedWorkTime
    summary.hoursPercent = est > 0 ? Math.max(0, Math.min(100, Math.round((est - Math.min(est, summary.remainingWorkTime)) * 100 / est))) : 0
    for (const name of ['estimatedWorkTime', 'remainingWorkTime', 'actualWorkTime', 'estimatedPoints', 'donePoints']) summary[name] = Math.round(summary[name] * 100) / 100
}

notesText = ''; itemCount = 0; openCount = 0; mergeRequestCount = 0
const release = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (release == null || release.workEffortTypeEnumId !== 'WetRelease') { ec.message.addError(ec.resource.expand('Release ${workEffortId} not found', '', {workEffortId})); return }
const L = (text) => ec.l10n.localize(text)
const toMillis = (value) => value == null || value === '' ? null : (/^-?\d+$/.test(String(value)) ? Number(String(value)) : Date.parse(String(value)))
const dayOf = (value) => toMillis(value) == null ? '' : ec.l10n.format(String(toMillis(value)), 'yyyy-MM-dd')
// text in markdown: no html, no emphasis or links by accident
const md = (text) => String(text == null ? '' : text).replace(/[\\`*_\[\]<>]/g, (ch) => '\\' + ch).replace(/\s+/g, ' ').trim()
version = release.workEffortName || workEffortId
const released = ['WeComplete', 'WeClosed'].includes(release.statusId)
dateText = dayOf(released ? (release.actualCompletionDate || release.estimatedCompletionDate) : release.estimatedCompletionDate)
title = dateText ? version + ' (' + dateText + ')' : version
const assocs = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'WeatRelease').conditionDate('fromDate', 'thruDate', null).list())
const ids = Array.from(new Set(assocs.map((assoc) => assoc.toWorkEffortId)))
const tasks = ids.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', ids).list()) : []
const keyOrder = (left, right) => {
    const split = (id) => { const match = /^(.*?)(\d+)$/.exec(String(id)); return match ? [match[1], Number(match[2])] : [String(id), 0] }
    const [lp, ln] = split(left.workEffortId); const [rp, rn] = split(right.workEffortId)
    return lp.localeCompare(rp) || ln - rn
}
tasks.sort(keyOrder)
const done = tasks.filter((task) => ['WeComplete', 'WeClosed'].includes(task.statusId))
const open = tasks.filter((task) => !['WeComplete', 'WeClosed', 'WeCancelled'].includes(task.statusId))
itemCount = done.length
openCount = open.length
const groups = [['Features', ['WepNewFeature', 'WepFeatureEnhance']], ['Fixes', ['WepFix']], ['Other', null]]
const parts = []
if (release.description && String(release.description).trim()) parts.push(String(release.description).trim())
const line = (task) => '- **' + task.workEffortId + '** ' + md(task.workEffortName)
for (const [label, purposes] of groups) {
    const rows = done.filter((task) => purposes ? purposes.includes(task.purposeEnumId) : !groups.some(([, others]) => others && others.includes(task.purposeEnumId)))
    if (rows.length) parts.push('### ' + L(label) + '\n\n' + rows.map(line).join('\n'))
}
if (!done.length) parts.push('_' + L(open.length ? 'No work items are done yet.' : 'No work items in this release.') + '_')
// the merged merge requests of its items, of the repositories the user may view (git hosting may not be in the build)
const mergeLines = []
ec.message.pushErrors()
try {
    const links = ids.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitMergeRequest').condition('workEffortId', 'in', ids).disableAuthz().list()) : []
    const mrIds = Array.from(new Set(links.map((link) => link.mergeRequestId)))
    const mrs = mrIds.length ? Array.from(ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', 'in', mrIds)
            .condition('statusId', 'GmrMerged').disableAuthz().list()) : []
    const viewable = {}
    const canView = (repositoryId) => {
        if (!(repositoryId in viewable)) {
            ec.message.pushErrors()
            try { viewable[repositoryId] = ec.factory.hasFeature('git') && !!ec.service.sync().name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameters({repositoryId}).call()?.canView && !ec.message.hasError() }
            catch (err) { viewable[repositoryId] = false }
            finally { ec.message.clearErrors(); ec.message.popErrors() }
        }
        return viewable[repositoryId]
    }
    mrs.sort((left, right) => String(left.repositoryId).localeCompare(String(right.repositoryId)) || Number(left.mergeRequestNum || 0) - Number(right.mergeRequestNum || 0))
    for (const mr of mrs) {
        if (!canView(mr.repositoryId)) continue
        const keys = links.filter((link) => link.mergeRequestId === mr.mergeRequestId).map((link) => link.workEffortId).sort()
        mergeLines.push('- ' + md(mr.repositoryId) + ' !' + mr.mergeRequestNum + ' ' + md(mr.title) + (keys.length ? ' (' + keys.join(', ') + ')' : '')
            + (mr.mergedDate ? ', ' + L('merged') + ' ' + dayOf(mr.mergedDate) : ''))
    }
} catch (err) {
    ec.logger.warn(`Release notes of ${workEffortId}: the merge requests were not read: ${err && err.message ? err.message : err}`)
} finally { ec.message.clearErrors(); ec.message.popErrors() }
mergeRequestCount = mergeLines.length
if (mergeLines.length) parts.push('### ' + L('Merge requests') + '\n\n' + mergeLines.join('\n'))
notesText = parts.join('\n\n') + '\n'

notesText = ''
const content = Array.from(ec.entity.find('mantle.work.effort.WorkEffortContent').condition('workEffortId', workEffortId)
        .condition('contentTypeEnumId', 'WectReleaseNotes').orderBy('-contentDate').list())[0] || null
if (content != null) {
    workEffortContentId = content.workEffortContentId
    contentDate = content.contentDate
    try {
        const ref = content.contentLocation ? ec.resource.getLocationReference(content.contentLocation) : null
        notesText = ref && ref.exists ? (ref.getText() || '') : ''
    } catch (err) {
        ec.logger.error(`Release notes of ${workEffortId}: ${content.contentLocation} not read: ${err && err.message ? err.message : err}`)
    }
}
for (const link of Array.from(ec.entity.find('mantle.work.effort.WikiPageWorkEffort').condition('workEffortId', workEffortId).list())) {
    const page = ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', link.wikiPageId).disableAuthz().one()
    if (page == null) continue
    wikiPageId = page.wikiPageId; wikiSpaceId = page.wikiSpaceId; pagePath = page.pagePath
    break
}

const release = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (release == null || release.workEffortTypeEnumId !== 'WetRelease') { ec.message.addError(ec.resource.expand('Release ${workEffortId} not found', '', {workEffortId})); return }
const content = Array.from(ec.entity.find('mantle.work.effort.WorkEffortContent').condition('workEffortId', workEffortId)
        .condition('contentTypeEnumId', 'WectReleaseNotes').orderBy('-contentDate').list())[0] || null
const root = String(ec.user.getPreference('mantle.content.root') || 'dbresource://mantle/content').replace(/\/+$/, '')
const location = content?.contentLocation || (root + '/work/' + workEffortId + '/release-notes.md')
ec.resource.getLocationReference(location).putText(String(notesText || ''))
if (content != null) {
    workEffortContentId = content.workEffortContentId
    ec.service.sync().name('update#mantle.work.effort.WorkEffortContent').parameters({workEffortContentId: workEffortContentId,
        contentDate: ec.user.nowTimestamp, userId: ec.user.userId || null}).call()
} else {
    workEffortContentId = ec.service.sync().name('create#mantle.work.effort.WorkEffortContent').parameters({workEffortId: workEffortId,
        contentTypeEnumId: 'WectReleaseNotes', contentLocation: location, description: ec.resource.expand('Release notes of ${version}', '',
        {version: release.workEffortName || workEffortId}), contentDate: ec.user.nowTimestamp, userId: ec.user.userId || null}).call()?.workEffortContentId
}

publishedList = []; failedList = []; notifiedCount = 0
const release = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (release == null || release.workEffortTypeEnumId !== 'WetRelease') { ec.message.addError(ec.resource.expand('Release ${workEffortId} not found', '', {workEffortId})); return }
const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', release.rootWorkEffortId).one()
const L = (text) => ec.l10n.localize(text)
const version = release.workEffortName || workEffortId
if (notesText != null && String(notesText).trim()) {
    ec.service.sync().name('mantle.work.ProjectServices.store#ReleaseNotes').parameters({workEffortId: workEffortId, notesText: notesText}).call()
    if (ec.message.hasError()) return
} else {
    notesText = ec.service.sync().name('mantle.work.ProjectServices.get#ReleaseNotes').parameters({workEffortId: workEffortId}).call()?.notesText || ''
    if (!String(notesText).trim()) notesText = ec.service.sync().name('mantle.work.ProjectServices.generate#ReleaseNotes').parameters({workEffortId: workEffortId}).call()?.notesText || ''
    if (ec.message.hasError()) return
}
const body = String(notesText).replace(/\r\n/g, '\n').trim()
const toMillis = (value) => value == null || value === '' ? null : (/^-?\d+$/.test(String(value)) ? Number(String(value)) : Date.parse(String(value)))
const released = ['WeComplete', 'WeClosed'].includes(release.statusId)
const when = released ? (release.actualCompletionDate || ec.user.nowTimestamp) : release.estimatedCompletionDate
const dateText = toMillis(when) == null ? '' : ec.l10n.format(String(toMillis(when)), 'yyyy-MM-dd')
// each way on its own: one that fails is a warning, and the others go on
const step = (name, run) => {
    ec.message.pushErrors()
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        publishedList.push(name)
    } catch (err) {
        const reason = err && err.message ? err.message : String(err)
        failedList.push(name)
        ec.logger.warn(`Release notes of ${workEffortId}: not published to ${name}: ${reason}`)
        ec.message.clearErrors(); ec.message.popErrors()
        ec.message.addMessage(ec.resource.expand('The notes were not published to ${name}: ${reason}', '', {name: L(name), reason}), 'warning')
        return
    }
    ec.message.clearErrors(); ec.message.popErrors()
}
if (toDocs) step('docs', () => {
    const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: release.rootWorkEffortId}).call()?.settings || {}
    const spaceId = settings.WstDocsWikiSpace
    if (!spaceId) throw new Error(L('the project has no documentation space'))
    const space = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', spaceId).disableAuthz().one()
    if (space == null || !space.rootPageLocation) throw new Error(ec.resource.expand('documentation space ${spaceId} not found', '', {spaceId}))
    const rootDir = String(space.rootPageLocation).replace(/\.[^/.]*$/, '')
    if (!ec.resource.getLocationReference(rootDir + '/Releases.md').exists) {
        ec.service.sync().name('org.moqui.impl.WikiServices.update#WikiPage').parameters({wikiSpaceId: spaceId, pageName: 'Releases',
            pageText: '# ' + L('Releases') + '\n\n' + L('The notes of each release of the project.') + '\n', versionNote: L('Releases')}).call()
        if (ec.message.hasError()) return
    }
    const pageName = String(version).replace(/[\/\\#?%]+/g, '-').trim() || workEffortId
    // the page: a title of its own, the groups one level up
    const pageText = '# ' + (project?.workEffortName || release.rootWorkEffortId) + ' ' + version + '\n\n'
        + (dateText ? '_' + (released ? L('Released') : L('Planned for')) + ' ' + dateText + '_\n\n' : '')
        + body.replace(/^###(?=\s)/gm, '##') + '\n'
    const saved = ec.service.sync().name('org.moqui.impl.WikiServices.update#WikiPage').parameters({wikiSpaceId: spaceId, parentPath: 'Releases',
        pageName: pageName, pageText: pageText, versionNote: ec.resource.expand('Release notes for ${version}', '', {version})}).call() || {}
    if (ec.message.hasError()) return
    wikiSpaceId = spaceId
    pagePath = saved.pagePath || ('Releases/' + pageName)
    wikiPageId = saved.wikiPageId || ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiPageId').parameters({wikiSpaceId: spaceId,
        pagePath: pagePath, createIfMissing: true}).call()?.wikiPageId
    if (wikiPageId && ec.entity.find('mantle.work.effort.WikiPageWorkEffort').condition({wikiPageId: wikiPageId, workEffortId: workEffortId}).count() === 0)
        ec.service.sync().name('create#mantle.work.effort.WikiPageWorkEffort').parameters({wikiPageId: wikiPageId, workEffortId: workEffortId}).call()
})
if (toChangelog) step('CHANGELOG.md', () => {
    const linked = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', release.rootWorkEffortId)
            .conditionDate('fromDate', 'thruDate', null).orderBy('repositoryId').list()).map((row) => row.repositoryId)
    const access = (id) => {
        if (!ec.factory.hasFeature('git')) return {}
        ec.message.pushErrors()
        try { const out = ec.service.sync().name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameters({repositoryId: id}).call() || {}; return ec.message.hasError() ? {} : out }
        finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
    if (repositoryId && !linked.includes(repositoryId)) throw new Error(ec.resource.expand('${repositoryId} is not a repository of the project', '', {repositoryId}))
    const target = repositoryId || linked.find((id) => access(id).canUpdate)
    if (!target) throw new Error(L('the project has no repository you may update'))
    const repoAccess = access(target)
    if (!repoAccess.canUpdate) throw new Error(ec.resource.expand('you may not update ${target}', '', {target}))
    const current = ec.service.sync().name('org.moqui.impl.GitServices.get#GitBlob').parameters({repositoryId: target, path: 'CHANGELOG.md'}).call()?.text
    if (ec.message.hasError()) return
    const section = '## ' + version + (dateText ? ' - ' + dateText : '') + '\n\n' + body + '\n'
    let text = current == null || !String(current).trim() ? '# ' + L('Changelog') + '\n\n' + section : String(current).replace(/\r\n/g, '\n')
    if (current != null && String(current).trim()) {
        const lines = text.split('\n')
        const escaped = version.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
        const own = new RegExp('^##\\s+\\[?v?' + escaped + '\\]?(\\s|$)')
        const start = lines.findIndex((one) => own.test(one))
        if (start >= 0) {
            let end = lines.findIndex((one, index) => index > start && /^##\s/.test(one))
            if (end < 0) end = lines.length
            lines.splice(start, end - start, ...section.replace(/\n$/, '').split('\n'), '')
        } else {
            // after the title and its lead paragraph: before the first section
            let at = lines.findIndex((one) => /^##\s/.test(one))
            if (at < 0) at = lines.length
            lines.splice(at, 0, ...section.replace(/\n$/, '').split('\n'), '')
        }
        text = lines.join('\n').replace(/\n{3,}/g, '\n\n').replace(/\n*$/, '\n')
    }
    repositoryId = target
    commitId = ec.service.sync().name('org.moqui.impl.GitServices.commit#GitFiles').parameters({repositoryId: target,
        message: ec.resource.expand('Release notes for ${version}', '', {version}), fileMap: {'CHANGELOG.md': text}}).call()?.commitId || null
})
if (notify) step('followers', () => {
    const followers = Array.from(ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', 'mantle.work.effort.WorkEffort')
            .condition('recordId', 'in', [workEffortId, release.rootWorkEffortId]).disableAuthz().list()).map((row) => row.userId)
    const userIds = Array.from(new Set(followers)).filter((userId) => userId && userId !== ec.user.userId)
    if (!userIds.length) return
    const me = ec.user.userAccount?.partyId ? ec.entity.find('mantle.party.PartyDetail').condition('partyId', ec.user.userAccount.partyId).one() : null
    const actorName = me ? (me.organizationName || [me.firstName, me.lastName].filter((part) => part).join(' ') || me.partyId) : (ec.user.username || 'System')
    const nm = ec.makeNotificationMessage().topic('ReleasePublished').userIds(userIds).message({workEffortId: workEffortId, version: version,
        rootWorkEffortId: release.rootWorkEffortId, projectName: project?.workEffortName || release.rootWorkEffortId, actorName: actorName,
        dateText: dateText, wikiPageId: wikiPageId || null, recordEntityName: 'mantle.work.effort.WorkEffort', recordId: workEffortId})
    if (typeof nm.record === 'function') nm.record('mantle.work.effort.WorkEffort', workEffortId)
    nm.send()
    notifiedCount = userIds.length
})

movedCount = 0; movedToWorkEffortId = null; publishedList = []
const release = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (release == null || release.workEffortTypeEnumId !== 'WetRelease') { ec.message.addError(ec.resource.expand('Release ${workEffortId} not found', '', {workEffortId})); return }
const version = release.workEffortName || workEffortId
const openStatuses = ['WeInPlanning', 'WeApproved', 'WeInProgress', 'WeOnHold']
if (!openStatuses.includes(release.statusId)) { ec.message.addError(ec.resource.expand('${version} is released or cancelled already', '', {version})); return }
const L = (text) => ec.l10n.localize(text)
const toMillis = (value) => value == null || value === '' ? Number.MAX_SAFE_INTEGER : (/^-?\d+$/.test(String(value)) ? Number(String(value)) : Date.parse(String(value)))
// where the items not done go
const others = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', release.rootWorkEffortId)
        .condition('workEffortTypeEnumId', 'WetRelease').condition('statusId', 'in', openStatuses).condition('workEffortId', 'not-equals', workEffortId).list())
if (moveUnfinishedTo === 'next') {
    const next = others.sort((left, right) => toMillis(left.estimatedCompletionDate) - toMillis(right.estimatedCompletionDate)
            || String(left.workEffortId).localeCompare(String(right.workEffortId)))[0]
    movedToWorkEffortId = next ? next.workEffortId : null
} else if (moveUnfinishedTo && moveUnfinishedTo !== 'none') {
    if (!others.some((other) => other.workEffortId === moveUnfinishedTo)) {
        ec.message.addError(ec.resource.expand('${moveUnfinishedTo} is not an open release of the project', '', {moveUnfinishedTo})); return
    }
    movedToWorkEffortId = moveUnfinishedTo
}
const assocs = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'WeatRelease').conditionDate('fromDate', 'thruDate', null).list())
const ids = Array.from(new Set(assocs.map((assoc) => assoc.toWorkEffortId)))
const open = ids.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', ids)
        .condition('statusId', 'not-in', ['WeComplete', 'WeClosed', 'WeCancelled']).list()) : []
for (const item of open) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('mantle.work.TaskServices.set#TaskPlanItem').parameters({workEffortId: item.workEffortId, assocTypeEnumId: 'WeatRelease',
            planWorkEffortId: movedToWorkEffortId}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        movedCount++
    } catch (err) {
        ec.logger.error(`Release ${workEffortId}: ${item.workEffortId} not moved: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters({workEffortId: workEffortId, statusId: 'WeComplete',
    actualCompletionDate: ec.user.nowTimestamp}).call()
if (ec.message.hasError()) return
const warn = (what, err) => {
    const reason = err && err.message ? err.message : String(err)
    ec.logger.warn(`Release ${workEffortId}: ${what}: ${reason}`)
    ec.message.addMessage(ec.resource.expand('${what}: ${reason}', '', {what: L(what), reason}), 'warning')
}
if (createTag) {
    let failure = null
    ec.message.pushErrors()
    try {
        const linked = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', release.rootWorkEffortId)
                .conditionDate('fromDate', 'thruDate', null).list()).map((row) => row.repositoryId)
        if (!repositoryId || !linked.includes(repositoryId)) throw new Error(ec.resource.expand('${repositoryId} is not a repository of the project', '', {repositoryId: repositoryId || '-'}))
        const name = String(tagName || '').trim() || (/^\d/.test(version) ? 'v' + version : version)
        const out = ec.service.sync().name('org.moqui.impl.GitServices.create#GitRef').parameters({repositoryId: repositoryId, refName: name, refType: 'tag',
            revision: revision || null, message: ec.resource.expand('Release ${version}', '', {version})}).call() || {}
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        tagRefName = out.refName || ('refs/tags/' + name)
        if (!String(tagRefName).startsWith('refs/')) tagRefName = 'refs/tags/' + tagRefName
        // the link the tag's own rule makes too (link#RefByName), now rather than when the push log runs
        ec.service.sync().name('mantle.work.GitServices.store#WorkEffortRef').parameters({workEffortId: workEffortId, repositoryId: repositoryId,
            refName: tagRefName, objectId: out.commitId || out.objectId || null, linkSourceEnumId: 'WglsReleaseVersion'}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        failure = err
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    if (failure) warn('The tag was not made', failure)
}
if (publish) {
    const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: release.rootWorkEffortId}).call()?.settings || {}
    const toDocs = !!settings.WstDocsWikiSpace
    if (toDocs || toChangelog || notify) {
        const out = ec.service.sync().name('mantle.work.ProjectServices.publish#ReleaseNotes').parameters({workEffortId: workEffortId, notesText: notesText || null,
            toDocs: toDocs, toChangelog: toChangelog, repositoryId: toChangelog ? (repositoryId || null) : null, notify: notify}).call() || {}
        if (ec.message.hasError()) { const reason = ec.message.getErrorsString(); ec.message.clearErrors(); warn('The notes were not published', reason) }
        wikiPageId = out.wikiPageId || null; pagePath = out.pagePath || null; commitId = out.commitId || null
        publishedList = Array.from(out.publishedList || [])
    }
}

const L = (text) => ec.l10n.localize(text)
const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (project == null || project.workEffortTypeEnumId !== 'WetProject') { ec.message.addError(ec.resource.expand('Project ${workEffortId} not found', '', {workEffortId})); return }
const own = ec.entity.find('mantle.work.effort.WorkEffortSetting').condition({workEffortId: workEffortId, settingTypeEnumId: 'WstDocsWikiSpace'}).one()
if (own != null && own.settingValue) { ec.message.addError(ec.resource.expand('The project has the documentation space ${space} already', '', {space: own.settingValue})); return }
if (!['repository', 'db'].includes(storage)) { ec.message.addError(ec.resource.expand('${storage} is not a storage for documentation: repository or db', '', {storage})); return }
let rootPageDirectory = 'dbresource://WikiSpace'
if (storage === 'repository') {
    const linked = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', workEffortId)
            .conditionDate('fromDate', 'thruDate', null).list()).map((row) => row.repositoryId)
    if (!repositoryId || !linked.includes(repositoryId)) { ec.message.addError(ec.resource.expand('${repositoryId} is not a repository of the project', '', {repositoryId: repositoryId || '-'})); return }
    ec.message.pushErrors()
    let canUpdate = false
