workEffortId = rootWorkEffortId + '-SP-' + sprintNumber
workEffortName = ec.resource.expand('Sprint ${sprintNumber}', '', {sprintNumber})
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const dayMillis = (text) => toMillis(ec.l10n.parseTimestamp(text + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'))
const addDays = (text, days) => { const d = new Date(text + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + days); return d.toISOString().substring(0, 10) }
