    endDay = addDays(lastDay, 14)
} else {
    startDay = dayText(toMillis(ec.user.nowTimestamp))
    endDay = addDays(startDay, 13)
}
while (weekday(endDay) === 0 || weekday(endDay) === 6) endDay = addDays(endDay, -1)
if (dayMillis(endDay) < dayMillis(startDay)) endDay = startDay
const latest = sprints.filter((row) => (estimateUnit === 'points' ? row.estimatedPoints : row.totalTimeAllowed) != null)
        .sort((left, right) => (toMillis(right.estimatedStartDate) || 0) - (toMillis(left.estimatedStartDate) || 0))[0]
capacity = latest ? (estimateUnit === 'points' ? latest.estimatedPoints : latest.totalTimeAllowed) : null

const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', rootWorkEffortId).one()
if (project == null || project.workEffortTypeEnumId !== 'WetProject') { ec.message.addError(ec.resource.expand('Project ${rootWorkEffortId} not found', '', {rootWorkEffortId})); return }
