        const party = ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()
        if (!party || party.partyTypeEnumId !== 'PtyPerson' || party.disabled === 'Y') continue
        const accounts = Array.from(ec.entity.find('moqui.security.UserAccount').condition('partyId', partyId).list())
        if (accounts.length && accounts.every((account) => account.disabled === 'Y')) { skippedList.push({partyId: partyId, reason: 'user account disabled'}); continue }
        const emailAddress = emailOf(partyId)
        if (!emailAddress) { skippedList.push({partyId: partyId, reason: 'no email address'}); continue }
        contactList.push({partyId: partyId, name: nameOf(partyId), emailAddress: emailAddress})
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

emailedAddressList = []; emailMessageIdList = []; skippedList = []
const L = (text) => ec.l10n.localize(text)
const escape = (text) => String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
let update = null, event = null, project = null, health = null
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    update = ec.entity.find('mantle.work.effort.WorkEffortUpdate').condition('workEffortId', workEffortId).condition('communicationEventId', communicationEventId).one()
    event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).one()
    project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    health = update?.healthEnumId ? ec.entity.find('moqui.basic.Enumeration').condition('enumId', update.healthEnumId).useCache(true).one() : null
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
// only an update posted for the client, a status update, of this project
if (!update || update.clientVisible !== 'Y' || !event || event.communicationEventTypeId !== 'StatusUpdate' || !project) return
const contacts = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectClientContacts').parameters({workEffortId: workEffortId,
    senderPartyId: event.fromPartyId || null}).call() || {}
if (ec.message.hasError()) return
skippedList = Array.from(contacts.skippedList || [])
if (!contacts.clientSignIn) { ec.logger.info(`Status update ${communicationEventId} of ${workEffortId}: not emailed, the client does not sign in to the project`); return }
const contactList = Array.from(contacts.contactList || [])
if (!contactList.length) return
if (!contacts.fromAddress) {
    ec.logger.error(`Status update ${communicationEventId} of ${workEffortId}: not emailed to the client, no address to send from`)
    for (const contact of contactList) skippedList.push({partyId: contact.partyId, reason: 'no address to send from'})
    return
}
const projectName = project.workEffortName || workEffortId
const subject = ec.resource.expand('${projectName}: ${subject}', '', {projectName: projectName, subject: event.subject || L('Status update')})
const state = [health ? ec.resource.expand('Health: ${health}', '', {health: health.description}) : '',
    update.percentComplete != null ? ec.resource.expand('${percent}% complete', '', {percent: update.percentComplete}) : ''].filter((part) => part).join(' · ')
const text = String(event.body || '')
const bodyText = [ec.resource.expand('Status update of ${projectName}', '', {projectName: projectName}), state, event.subject || '', text].filter((part) => part).join('\n\n')
const body = '<html><body><p><strong>' + escape(ec.resource.expand('Status update of ${projectName}', '', {projectName: projectName})) + '</strong></p>'
    + (state ? '<p>' + escape(state) + '</p>' : '') + (event.subject ? '<h3>' + escape(event.subject) + '</h3>' : '')
    + text.split(/\n{2,}/).map((para) => '<p>' + escape(para).replace(/\n/g, '<br>') + '</p>').join('') + '</body></html>'
for (const contact of contactList) {
    ec.message.pushErrors()
    try {
        const sent = ec.service.sync().name('org.moqui.impl.EmailServices.send#EmailTemplate').parameters({emailTemplateId: 'MANTLE_PROJECT_UPDATE',
            toAddresses: contact.emailAddress, bodyParameters: {subject: subject, fromAddress: contacts.fromAddress, fromName: contacts.fromName},
            body: body, bodyText: bodyText}).requireNewTransaction(true).call() || {}
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        if (sent.emailMessageId) emailMessageIdList.push(sent.emailMessageId)
        emailedAddressList.push(contact.emailAddress)
    } catch (err) {
        const reason = String(err && err.message ? err.message : err)
        ec.logger.error(`Status update ${communicationEventId} of ${workEffortId}: email to party ${contact.partyId} not sent: ${reason}`)
        skippedList.push({partyId: contact.partyId, reason: reason})
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}

activityList = []; hasMore = false; failedSources = []
const size = Math.max(1, Math.min(Number(pageSize) || 20, 100))
const page = Math.max(0, Number(pageIndex) || 0)
const wanted = (page + 1) * size + 1
let want = kinds ? String(kinds).split(',').map((kind) => kind.trim()).filter((kind) => kind) : ['status', 'comment', 'update', 'commit']
const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (project == null) return
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
// a client (impl-projects.md P10): of a project it sees, the status changes of its shared items and the status updates
// posted for it; never notes, messages or commits
const clientShared = vis.isClient ? new Set(Array.from(vis.itemVisibilityIds || [])) : null
if (clientShared) {
    if (!Array.from(vis.visibleProjectIds || []).includes(workEffortId)) return
    want = want.filter((kind) => kind === 'status' || kind === 'update')
}
const manages = !!vis.allProjects || Array.from(vis.managedProjectIds || []).includes(workEffortId)
const restrictedOk = new Set(Array.from(vis.restrictedItemIds || []))
// the project and its items, by id (an item it may not see is left out)
const items = new Map([[workEffortId, project.workEffortName || workEffortId]])
for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', workEffortId).selectField('workEffortId')
        .selectField('workEffortName').selectField('visibilityEnumId').selectField('workEffortTypeEnumId').limit(5000).list()) {
    if (clientShared && row.workEffortTypeEnumId === 'WetTask' && !clientShared.has(row.visibilityEnumId)) continue
    if (clientShared && !['WetTask', 'WetMilestone', 'WetRelease'].includes(row.workEffortTypeEnumId)) continue
    if (!manages && ['WevRestricted', 'WevConfidential'].includes(row.visibilityEnumId) && !restrictedOk.has(row.workEffortId)) continue
    items.set(row.workEffortId, row.workEffortName || row.workEffortId)
}
const ids = Array.from(items.keys())
const userNames = new Map()
const userName = (userId) => {
    if (!userId) return ''
    if (!userNames.has(userId)) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()
        userNames.set(userId, account ? (account.userFullName || account.username || userId) : userId)
    }
    return userNames.get(userId)
}
const partyNames = new Map()
const partyName = (partyId) => {
    if (!partyId) return ''
    if (!partyNames.has(partyId)) {
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).disableAuthz().one()
        partyNames.set(partyId, party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || partyId) : partyId)
    }
    return partyNames.get(partyId)
}
const millis = (value) => value == null ? 0 : Number(String(value))
const entries = []
const source = (name, run) => {
    try { run() } catch (err) {
        failedSources.push(name)
        ec.logger.error(`Activity of project ${workEffortId}: the ${name} source failed and is left out: ${err && err.message ? err.message : err}`)
    }
}
const chunks = (list, n) => { const out = []; for (let i = 0; i < list.length; i += n) out.push(list.slice(i, i + n)); return out }

if (want.includes('status')) source('status', () => {
    const statusText = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id) : ''
    for (const part of chunks(ids, 1000)) for (const row of ec.entity.find('moqui.entity.EntityAuditLog').condition('changedEntityName', 'mantle.work.effort.WorkEffort')
            .condition('changedFieldName', 'statusId').condition('pkPrimaryValue', 'in', part).orderBy('-changedDate').limit(wanted).disableAuthz().list()) {
        if (!row.oldValueText) continue
        entries.push({kind: 'status', date: millis(row.changedDate), workEffortId: row.pkPrimaryValue, workEffortName: items.get(row.pkPrimaryValue),
            title: ec.resource.expand('${from} to ${to}', '', {from: statusText(row.oldValueText), to: statusText(row.newValueText)}),
            text: '', userId: row.changedByUserId || null, authorName: userName(row.changedByUserId), key: 'audit-' + row.auditHistorySeqId})
    }
})
// a client's status updates: those posted for the client (WorkEffortUpdate clientVisible Y)
const clientUpdateIds = new Set()
if (clientShared) for (const row of ec.entity.find('mantle.work.effort.WorkEffortUpdate').condition('workEffortId', workEffortId)
        .condition('clientVisible', 'Y').disableAuthz().list()) clientUpdateIds.add(row.communicationEventId)
if (want.includes('comment') || want.includes('update')) source('comment', () => {
    const byEvent = new Map()
    for (const part of chunks(ids, 1000)) for (const row of ec.entity.find('mantle.work.effort.WorkEffortCommEvent').condition('workEffortId', 'in', part)
            .selectField('workEffortId').selectField('communicationEventId').list()) byEvent.set(row.communicationEventId, row.workEffortId)
    const eventIds = Array.from(byEvent.keys())
    for (const part of chunks(eventIds, 1000)) for (const event of ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', 'in', part)
            .condition(ec.entity.conditionFactory.makeCondition('statusId', 'not-equals', 'CeCancelled', true)).orderBy('-entryDate').limit(wanted).list()) {
        const isUpdate = event.communicationEventTypeId === 'StatusUpdate'
        if (!want.includes(isUpdate ? 'update' : 'comment')) continue
        if (clientShared && !clientUpdateIds.has(event.communicationEventId)) continue
        const plain = String(event.body || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim()
        const itemId = byEvent.get(event.communicationEventId)
        entries.push({kind: isUpdate ? 'update' : 'comment', date: millis(event.entryDate), workEffortId: itemId, workEffortName: items.get(itemId),
            title: isUpdate ? (event.subject || ec.l10n.localize('Status update')) : (event.communicationEventTypeId === 'Comment' ? ec.l10n.localize('Note') : ec.l10n.localize('Message')),
            text: plain.length > 160 ? plain.substring(0, 157) + '...' : plain, userId: null, authorName: partyName(event.fromPartyId),
            communicationEventId: event.communicationEventId, key: 'comm-' + event.communicationEventId})
    }
})
if (want.includes('commit')) source('commit', () => {
    const seen = new Set()
    for (const part of chunks(ids, 1000)) for (const row of ec.entity.find('mantle.work.effort.WorkEffortGitCommit').condition('workEffortId', 'in', part)
            .orderBy('-commitDate').limit(wanted).list()) {
        const key = row.repositoryId + '/' + row.commitId + '/' + row.workEffortId
        if (seen.has(key)) continue
        seen.add(key)
        entries.push({kind: 'commit', date: millis(row.commitDate || row.linkedDate), workEffortId: row.workEffortId, workEffortName: items.get(row.workEffortId),
            title: ec.resource.expand('Commit ${commit} in ${repositoryId}', '', {commit: String(row.commitId).substring(0, 8), repositoryId: row.repositoryId}),
            text: row.summary || '', userId: null, authorName: row.authorName || '', commitId: row.commitId, repositoryId: row.repositoryId, key: 'commit-' + key})
    }
})
entries.sort((a, b) => b.date - a.date || String(a.key).localeCompare(String(b.key)))
hasMore = entries.length > (page + 1) * size
activityList = entries.slice(page * size, (page + 1) * size)

counts = {myOpen: null, dueWeek: null, overdue: null, reviewsWaiting: null, hoursWeek: null, expectedWeek: null, timesheetStatusId: null,
    projectsAtRisk: null, milestonesSoon: null, timesheetsToApprove: null, allocationRequests: null, unbilledAmount: null, unbilledCurrencyUomId: null}
atRiskProjectIds = []
failedParts = []
const part = (name, run) => {
    try { run() } catch (err) {
        failedParts.push(name)
        ec.logger.error(`Projects home counts: ${name} failed and is left out: ${err && err.message ? err.message : err}`)
    }
}
const cf = ec.entity.conditionFactory
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const me = vis.userPartyId || null
const all = !!vis.allProjects
const visibleIds = Array.from(vis.visibleProjectIds || [])
const templateIds = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetProject')
        .condition('isTemplate', 'Y').selectField('workEffortId').list()).map((row) => row.workEffortId)
const nowMillis = Number(String(ec.user.nowTimestamp))
const today = ec.user.getPeriodRange('day', '0')
const todayStart = today ? Number(String(today[0])) : nowMillis
const open = ['WeComplete', 'WeClosed', 'WeCancelled']

part('myWork', () => {
    if (!me || (!all && !visibleIds.length)) { counts.myOpen = 0; counts.dueWeek = 0; counts.overdue = 0; return }
    const assigned = Array.from(new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('partyId', me).condition('roleTypeId', 'Assignee')
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true))
            .selectField('workEffortId').list()).map((row) => row.workEffortId)))
    if (!assigned.length) { counts.myOpen = 0; counts.dueWeek = 0; counts.overdue = 0; return }
    const base = [cf.makeCondition('workEffortId', 'in', assigned), cf.makeCondition('workEffortTypeEnumId', 'equals', 'WetTask'),
        cf.makeCondition('rootWorkEffortId', 'is-not-null', null), cf.makeCondition('statusId', 'not-in', open)]
    if (!all) base.push(cf.makeCondition('rootWorkEffortId', 'in', visibleIds))
    if (templateIds.length) base.push(cf.makeCondition('rootWorkEffortId', 'not-in', templateIds))
    const count = (more) => ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition(base.concat(more), 'and')).count()
    counts.myOpen = count([])
    counts.dueWeek = count([cf.makeCondition('estimatedCompletionDate', 'greater-equals', new Date(todayStart)),
        cf.makeCondition('estimatedCompletionDate', 'less-than', new Date(todayStart + 7 * 86400000))])
    counts.overdue = count([cf.makeCondition('estimatedCompletionDate', 'less-than', new Date(todayStart))])
})
part('reviewsWaiting', () => {
    if (!ec.user.userId) { counts.reviewsWaiting = 0; return }
    // the framework's merge requests; git hosting is a build feature: without it the count stays null. The call runs in a
    // transaction of its own, so a failure leaves this one usable for the other parts
    if (!ec.factory.hasFeature('git')) return
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.impl.GitReviewServices.find#MergeRequests').parameters({waitingForUserId: ec.user.userId,
            pageSize: 1}).requireNewTransaction(true).call() || {}
        if (ec.message.hasError()) {
            const errors = ec.message.getErrorsString()
            if (/not built into/.test(errors)) return
            throw new Error(errors)
        }
        counts.reviewsWaiting = Number(out.mergeRequestListCount || 0)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
})
part('hoursWeek', () => {
    if (!me) { counts.hoursWeek = 0; return }
    const policyOut = ec.service.sync().name('mantle.work.TimesheetServices.get#TimesheetPolicy').parameters({partyId: me}).call() || {}
    const policy = policyOut.policy || {}
    const week = ec.service.sync().name('mantle.work.TimesheetServices.get#WeekRange').parameters({weekStart: policy.weekStart || 1}).call()
    let hours = 0
    for (const row of ec.entity.find('mantle.work.time.TimeEntry').condition('partyId', me).condition('fromDate', 'greater-equals', week.fromDate)
            .condition('fromDate', 'less-than', week.thruDate).selectField('hours').list()) hours += Number(String(row.hours ?? 0))
    counts.hoursWeek = Math.round(hours * 100) / 100
    const sheet = ec.service.sync().name('mantle.work.TimesheetServices.get#PartyTimesheet').parameters({partyId: me, date: week.weekStartDay, make: false}).call() || {}
    counts.timesheetStatusId = sheet.timesheet?.statusId || 'TmshInProcess'
    counts.expectedWeek = Number(String(ec.service.sync().name('mantle.work.TimesheetServices.get#WeekDays').parameters({dayList: week.dayList, policy: policy,
        organizationPartyId: policyOut.organizationPartyId || null, partyId: me}).call()?.expectedTotal ?? 0))
})
if (managers) {
    const managed = all ? null : Array.from(vis.managedProjectIds || [])
    const projects = () => {
        if (managed != null && !managed.length) return []
        let find = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetProject').condition('statusId', 'not-in', open)
        if (managed != null) find = find.condition('workEffortId', 'in', managed)
        return Array.from(find.limit(1000).list()).filter((row) => row.isTemplate !== 'Y')
    }
    part('projectsAtRisk', () => {
        for (const project of projects()) {
            let risky = ['WehAtRisk', 'WehOffTrack'].includes(project.healthEnumId)
            if (!risky) {
                const stats = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectStats').parameters({workEffort: project}).call() || {}
                risky = !!(stats.projectWarning || stats.projectDanger)
            }
            if (risky) atRiskProjectIds.push(project.workEffortId)
        }
        counts.projectsAtRisk = atRiskProjectIds.length
    })
    part('timesheetsToApprove', () => {
        const out = ec.service.sync().name('mantle.work.TimesheetServices.find#Timesheets').parameters({list: 'toApprove', withCounts: false}).call() || {}
        counts.timesheetsToApprove = Array.from(out.rowList || []).length
    })
    part('milestonesSoon', () => {
        const ids = projects().map((project) => project.workEffortId)
        counts.milestonesSoon = !ids.length ? 0 : ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetMilestone')
                .condition('rootWorkEffortId', 'in', ids).condition(cf.makeCondition('statusId', 'not-in', open, true))
                .condition('estimatedCompletionDate', 'greater-equals', new Date(todayStart))
                .condition('estimatedCompletionDate', 'less-than', new Date(todayStart + 14 * 86400000)).count()
    })
    // impl-projects.md P7: the requested allocations, for those who decide them (null for a manager who does not)
    part('allocationRequests', () => {
        if (!ec.user.isInGroup('ADMIN') && !ec.user.hasPermission('ALLOCATION_APPROVE')) return
        counts.allocationRequests = Number(ec.service.sync().name('mantle.work.ResourceServices.find#Allocations').parameters({list: 'requested',
            withCounts: true, limit: 1}).call()?.counts?.requested ?? 0)
    })
    // impl-projects.md P8a: the amount of the billable time not invoiced (get#UnbilledSummary), for those who manage money
    part('unbilledAmount', () => {
        if (!ec.user.isInGroup('ADMIN') && !ec.user.hasPermission('TIME_ENTRY_RATE')) return
        ec.message.pushErrors()
        try {
            const out = ec.service.sync().name('mantle.work.ProjectServices.get#UnbilledSummary').call() || {}
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            counts.unbilledAmount = out.totals?.mixedCurrency ? null : (out.totals?.amount ?? toDecimal(0))
            counts.unbilledCurrencyUomId = out.totals?.currencyUomId || null
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
    })
}

projectList = []
totals = {projectCount: 0, entryCount: 0, hours: toDecimal(0), amount: toDecimal(0), readyHours: toDecimal(0), readyAmount: toDecimal(0),
    missingRateCount: 0, milestoneDueCount: 0, milestoneDueAmount: toDecimal(0), currencyUomId: null, mixedCurrency: false, byClient: []}
if (!(ec.user.userId && (ec.user.isInGroup('ADMIN') || ec.user.hasPermission('TIME_ENTRY_RATE')))) {
    ec.message.addError(ec.l10n.localize('Only those who manage money see what is unbilled')); return }
const cf = ec.entity.conditionFactory
const zero = toDecimal(0)
const thru = thruDate != null ? thruDate : ec.user.nowTimestamp
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    const all = !!vis.allProjects
    const visible = Array.from(vis.visibleProjectIds || [])
    if (workEffortId && !all && !visible.includes(workEffortId)) {
        ec.message.addError(ec.resource.expand('Project ${workEffortId} is not available', '', {workEffortId})); return }
    if (!all && !visible.length) return
    const scope = workEffortId ? [workEffortId] : (all ? null : visible)
    const conds = [cf.makeCondition('invoiceId', 'is-null', null), cf.makeCondition('rateTypeEnumId', 'not-equals', 'RatpNoCharge', true),
        cf.makeCondition('thruDate', 'is-not-null', null), cf.makeCondition('thruDate', 'less-equals', thru), cf.makeCondition('workEffortId', 'is-not-null', null)]
    if (scope) conds.push(cf.makeCondition([cf.makeCondition('rootWorkEffortId', 'in', scope), cf.makeCondition('workEffortId', 'in', scope)], 'or'))
    const entries = Array.from(ec.entity.find('mantle.work.time.TimeEntryAndWorkEffort').condition(cf.makeCondition(conds, 'and'))
            .selectField('timeEntryId').selectField('partyId').selectField('workEffortId').selectField('workEffortName').selectField('workEffortTypeEnumId')
            .selectField('rootWorkEffortId').selectField('fromDate').selectField('thruDate').selectField('hours').selectField('clientHourRate')
            .selectField('rateAmountId').selectField('timesheetId').selectField('comments')
            .orderBy('fromDate').orderBy('timeEntryId').limit(50000).list())
    // the projects of the entries
    const byProject = {}
    for (const entry of entries) {
        const root = entry.workEffortTypeEnumId === 'WetProject' ? entry.workEffortId : entry.rootWorkEffortId
        if (!root) continue
        if (scope && !scope.includes(root)) continue
        ;(byProject[root] || (byProject[root] = [])).push(entry)
    }
    // the milestone shares due (reached, approved, not billed): a project with only those is listed too
    const dueByProject = {}
    const billingOut = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneBilling').parameters({rootWorkEffortId: workEffortId || null, dueOnly: true}).call() || {}
    for (const share of Array.from(billingOut.shareList || [])) {
        if (scope && !scope.includes(share.rootWorkEffortId)) continue
        ;(dueByProject[share.rootWorkEffortId] || (dueByProject[share.rootWorkEffortId] = [])).push(share)
    }
    const projectIds = Array.from(new Set(Object.keys(byProject).concat(Object.keys(dueByProject))))
    if (!projectIds.length) return
    const projects = {}
    for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', projectIds).list()) projects[row.workEffortId] = row
    // the parties of each project: the client and the vendor
    const roleOf = {}
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', 'in', projectIds)
            .condition('roleTypeId', 'in', ['Customer', 'CustomerBillTo', 'Vendor', 'VendorBillFrom']).conditionDate('fromDate', 'thruDate', null).orderBy('fromDate').list()) {
        const parties = roleOf[row.workEffortId] || (roleOf[row.workEffortId] = {})
        const kind = row.roleTypeId.startsWith('Customer') ? 'client' : 'vendor'
        if (!parties[kind]) parties[kind] = row.partyId
    }
    const names = {}
    const nameOf = (id) => {
        if (!id) return ''
        if (!(id in names)) {
            const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
            names[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
        }
        return names[id]
    }
    // the timesheets' statuses
    const sheetIds = Array.from(new Set(entries.map((entry) => entry.timesheetId).filter((id) => id)))
    const sheetStatus = {}
    for (let i = 0; i < sheetIds.length; i += 1000) for (const row of ec.entity.find('mantle.work.time.Timesheet')
            .condition('timesheetId', 'in', sheetIds.slice(i, i + 1000)).selectField('timesheetId').selectField('statusId').list()) sheetStatus[row.timesheetId] = row.statusId
    // the rates of the entries with no hour rate of their own
    const rates = {}
    const rateOf = (id) => {
        if (!id) return null
        if (!(id in rates)) rates[id] = ec.entity.find('mantle.humanres.rate.RateAmount').condition('rateAmountId', id).useCache(true).one()
        return rates[id]
    }
    const orgCurrency = {}
    const currencyOfOrg = (orgId) => {
        if (!orgId) return null
        if (!(orgId in orgCurrency)) orgCurrency[orgId] = ec.entity.find('mantle.ledger.config.PartyAcctgPreference').condition('organizationPartyId', orgId).one()?.baseCurrencyUomId || null
        return orgCurrency[orgId]
    }
    const clientTotals = {}
    const currencies = new Set()
    for (const projectId of projectIds) {
        const project = projects[projectId]
        if (!project || project.isTemplate === 'Y') continue
        const parties = roleOf[projectId] || {}
        if (clientPartyId && parties.client !== clientPartyId) continue
        const row = {workEffortId: projectId, workEffortName: project.workEffortName || projectId, clientPartyId: parties.client || null,
            clientName: nameOf(parties.client), vendorPartyId: parties.vendor || null, currencyUomId: null, entryCount: 0, hours: zero, amount: zero,
            readyCount: 0, readyHours: zero, readyAmount: zero, waitingHours: zero, openHours: zero, missingRateCount: 0, readyMissingRateCount: 0,
            firstDate: null, lastDate: null, expenseCount: 0, expenseAmount: zero, lastInvoiceId: null, lastInvoiceDate: null, draftInvoiceList: [],
            milestoneDueList: [], milestoneDueCount: 0, milestoneDueAmount: zero, timeReady: false, canInvoice: false, cannotReason: null}
        if (withEntries) row.entryList = []
        for (const share of dueByProject[projectId] || []) {
            row.milestoneDueList.push({workEffortId: share.workEffortId, milestoneName: share.milestoneName, orderId: share.orderId, orderItemSeqId: share.orderItemSeqId,
                itemDescription: share.itemDescription, percent: share.percent, invoicePercent: share.invoicePercent, amount: share.amount,
                currencyUomId: share.currencyUomId, reachedDate: share.reachedDate})
            row.milestoneDueCount++
            row.milestoneDueAmount = row.milestoneDueAmount.add(share.amount)
            if (!row.currencyUomId) row.currencyUomId = share.currencyUomId
        }
        for (const entry of byProject[projectId] || []) {
            const hours = toDecimal(entry.hours ?? 0)
            const rateAmount = entry.clientHourRate == null ? rateOf(entry.rateAmountId) : null
            const rate = entry.clientHourRate != null ? toDecimal(entry.clientHourRate) : (rateAmount?.rateAmount != null ? toDecimal(rateAmount.rateAmount) : null)
            if (rateAmount?.rateCurrencyUomId && !row.currencyUomId) row.currencyUomId = rateAmount.rateCurrencyUomId
            const amount = rate == null ? null : hours.multiply(rate).setScale(2, 'HALF_UP')
            const status = entry.timesheetId ? (sheetStatus[entry.timesheetId] || 'TmshInProcess') : 'TmshInProcess'
            const ready = status === 'TmshApproved'
            row.entryCount++
            row.hours = row.hours.add(hours)
            if (amount != null) row.amount = row.amount.add(amount); else row.missingRateCount++
            if (ready) {
                row.readyCount++
                row.readyHours = row.readyHours.add(hours)
                if (amount != null) row.readyAmount = row.readyAmount.add(amount); else row.readyMissingRateCount++
            } else if (status === 'TmshCompleted') row.waitingHours = row.waitingHours.add(hours)
            else row.openHours = row.openHours.add(hours)
            const from = entry.fromDate == null ? null : Number(String(entry.fromDate))
            if (from != null && (row.firstDate == null || from < row.firstDate)) row.firstDate = from
            if (from != null && (row.lastDate == null || from > row.lastDate)) row.lastDate = from
            if (withEntries) row.entryList.push({timeEntryId: entry.timeEntryId, partyId: entry.partyId, personName: nameOf(entry.partyId),
                workEffortId: entry.workEffortId, workEffortName: entry.workEffortName || '', fromDate: from,
                thruDate: entry.thruDate == null ? null : Number(String(entry.thruDate)), hours: hours, rate: rate, amount: amount, ready: ready,
                sheetStatusId: status, comments: entry.comments || '', missingRate: rate == null})
        }
        if (!row.currencyUomId) row.currencyUomId = project.costUomId || currencyOfOrg(parties.vendor) || 'USD'
        // the project's invoices: the latest client invoice, its drafts, and its expenses not billed through
        for (const inv of ec.entity.find('mantle.work.effort.WorkEffortInvoiceDetail').condition('workEffortId', projectId)
                .condition('statusId', 'not-equals', 'InvoiceCancelled').orderBy('-invoiceDate').list()) {
            if (parties.client && inv.toPartyId === parties.client) {
                if (!row.lastInvoiceId) { row.lastInvoiceId = inv.invoiceId; row.lastInvoiceDate = inv.invoiceDate == null ? null : Number(String(inv.invoiceDate)) }
                if (inv.statusId === 'InvoiceInProcess') row.draftInvoiceList.push({invoiceId: inv.invoiceId,
                    invoiceDate: inv.invoiceDate == null ? null : Number(String(inv.invoiceDate)), invoiceTotal: toDecimal(inv.invoiceTotal ?? 0)})
            } else if (inv.statusId === 'InvoicePmtSent' && inv.toPartyId !== parties.client && inv.fromPartyId !== parties.vendor) {
                row.expenseCount++
                row.expenseAmount = row.expenseAmount.add(toDecimal(inv.invoiceTotal ?? 0))
            }
        }
        const timeReason = !row.readyCount ? ec.l10n.localize('No approved time yet')
            : row.readyMissingRateCount ? ec.resource.expand('${count} approved entries have no client rate', '', {count: row.readyMissingRateCount}) : null
        row.timeReady = timeReason == null
        row.cannotReason = !row.clientPartyId ? ec.l10n.localize('The project has no client')
            : !row.vendorPartyId ? ec.l10n.localize('The project has no vendor to bill from')
            : row.milestoneDueCount ? null : timeReason
        row.canInvoice = row.cannotReason == null
        currencies.add(row.currencyUomId)
        projectList.push(row)
        totals.projectCount++
        totals.entryCount += row.entryCount
        totals.hours = totals.hours.add(row.hours)
        totals.amount = totals.amount.add(row.amount)
        totals.readyHours = totals.readyHours.add(row.readyHours)
        totals.readyAmount = totals.readyAmount.add(row.readyAmount)
        totals.missingRateCount += row.missingRateCount
        totals.milestoneDueCount += row.milestoneDueCount
        totals.milestoneDueAmount = totals.milestoneDueAmount.add(row.milestoneDueAmount)
        const clientKey = row.clientPartyId || ''
        const client = clientTotals[clientKey] || (clientTotals[clientKey] = {clientPartyId: row.clientPartyId, clientName: row.clientName, hours: zero, amount: zero})
        client.hours = client.hours.add(row.hours)
        client.amount = client.amount.add(row.amount)
    }
    projectList.sort((a, b) => (a.clientName || '￿').localeCompare(b.clientName || '￿') || a.workEffortName.localeCompare(b.workEffortName))
    totals.mixedCurrency = currencies.size > 1
    totals.currencyUomId = currencies.size === 1 ? Array.from(currencies)[0] : null
    // amounts in more than one currency have no one total
    if (totals.mixedCurrency) { totals.amount = null; totals.readyAmount = null; totals.milestoneDueAmount = null }
    totals.byClient = Object.values(clientTotals).sort((a, b) => b.amount.compare(a.amount))
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

items = []
label = 'Projects'
const L = (text, values) => ec.resource.expand(ec.l10n.localize(text), '', values || {})
const me = ec.user.userAccount?.partyId || null
if (!me || !ec.user.userId) return
const part = (name, run) => {
    ec.message.pushErrors()
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.error(`Projects Today of ${ec.user.userId}: ${name} failed and is left out: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const base = {workEffortId: null, requestId: null, dueDate: null, startDate: null, endDate: null, allDay: false, priority: null,
    statusId: null, assignees: [], canUpdate: false, hasCallLink: false}
const nowMillis = Number(String(ec.user.nowTimestamp))

part('timer', () => {
    const timer = ec.service.sync().name('mantle.work.TimesheetServices.get#Timer').call()?.timer
    if (!timer) return
    items.push(Object.assign({}, base, {kind: 'timer', timeEntryId: timer.timeEntryId, title: timer.workEffortId
            ? timer.workEffortId + ' ' + (timer.workEffortName || '') : L('Timer on no work item'), startDate: new Date(Number(timer.fromDate)),
        elapsedMinutes: timer.elapsedMinutes, record: timer.workEffortId ? {recordEntityName: 'mantle.work.effort.WorkEffort', recordId: timer.workEffortId,
            recordName: timer.projectName || null} : null}))
})
part('reviews', () => {
    // in a transaction of its own: without git hosting the call fails, which would leave this one rollback-only
    const out = ec.service.sync().name('org.moqui.impl.GitReviewServices.find#MergeRequests').parameters({waitingForUserId: ec.user.userId, pageSize: 10})
            .requireNewTransaction(true).call() || {}
    if (ec.message.hasError()) {
        // git hosting is a build feature: without it there are no reviews, not a failure
        if (/not built into/.test(ec.message.getErrorsString())) { ec.message.clearErrors(); return }
        return
    }
    for (const request of Array.from(out.mergeRequestList || [])) items.push(Object.assign({}, base, {kind: 'review', title: '!' + request.mergeRequestNum + ' ' + (request.title || ''),
        mergeRequestId: request.mergeRequestId, record: {recordEntityName: 'moqui.resource.GitMergeRequest', recordId: request.mergeRequestId,
            recordName: request.repositoryId + (request.authorName ? ' · ' + request.authorName : '')}}))
})
part('timesheets', () => {
    const policy = ec.service.sync().name('mantle.work.TimesheetServices.get#TimesheetPolicy').call()?.policy || {}
    const week = ec.service.sync().name('mantle.work.TimesheetServices.get#WeekRange').parameters({weekStart: policy.weekStart || 1}).call()
    const workDays = Array.from(policy.workDays || [1, 2, 3, 4, 5]).map(Number)
    const isoOf = (day) => { const js = new Date(day + 'T12:00:00Z').getUTCDay(); return js === 0 ? 7 : js }
    const lastWorkDay = Array.from(week.dayList).filter((day) => workDays.includes(isoOf(day))).pop() || week.dayList[6]
    const today = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
    const thisFrom = Number(String(week.fromDate))
    const cf = ec.entity.conditionFactory
    const sheets = Array.from(ec.entity.find('mantle.work.time.Timesheet').condition('partyId', me)
            .condition(cf.makeCondition('statusId', 'equals', 'TmshInProcess', true))
            .condition('fromDate', 'greater-equals', new Date(thisFrom - 8 * 7 * 86400000 - 86400000))
            .condition('fromDate', 'less-than', new Date(thisFrom + 7 * 86400000 - 86400000)).orderBy('fromDate').disableAuthz().list())
    for (const sheet of sheets) {
        const middle = Number(String(sheet.fromDate)) + 3.5 * 86400000
        const isThisWeek = middle >= thisFrom && middle < thisFrom + 7 * 86400000
        if (isThisWeek && today < lastWorkDay) continue
        let hours = 0
        for (const entry of ec.entity.find('mantle.work.time.TimeEntry').condition('timesheetId', sheet.timesheetId).selectField('hours').disableAuthz().list())
            hours += Number(String(entry.hours ?? 0))
        if (!hours) continue
        const weekStart = ec.l10n.format(String(Number(String(sheet.fromDate)) + 43200000), 'yyyy-MM-dd')
        const weekText = ec.l10n.format(String(Number(String(sheet.fromDate)) + 43200000), 'MMM d')
        const hoursText = ec.l10n.format(Math.round(hours * 100) / 100, '#,##0.##')
        items.push(Object.assign({}, base, {kind: 'timesheet', timesheetId: sheet.timesheetId, weekStart: weekStart, hours: Math.round(hours * 100) / 100,
            returned: !!sheet.comments, overdue: !isThisWeek,
            title: sheet.comments ? L('Returned: fix and submit your week of ${week} (${hours} h)', {week: weekText, hours: hoursText})
                : L('Submit your week of ${week} (${hours} h)', {week: weekText, hours: hoursText}),
            record: {recordEntityName: 'mantle.work.time.Timesheet', recordId: sheet.timesheetId, recordName: L('Week of ${week}', {week: weekText})}}))
    }
})
part('triage', () => {
    const cf = ec.entity.conditionFactory
    const wasDisabled = ec.artifactExecution.disableAuthz()
    try {
        // the projects whose triage is the user's: named as the triage assignee, or a manager of one that names none
        const roles = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('partyId', me).condition('roleTypeId', 'in', ['ProjectManager', 'Manager'])
                .conditionDate('fromDate', 'thruDate', null).selectField('workEffortId').list()).map((row) => row.workEffortId)
        const triaged = new Set()
        for (const projectId of new Set(roles)) {
            const settings = ec.service.sync().name('mantle.request.RequestServices.get#IntakeSettings').parameters({workEffortId: projectId}).call()?.settings || {}
            if (!settings.triagePartyId || settings.triagePartyId === me) triaged.add(projectId)
        }
        for (const row of ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('settingTypeEnumId', 'WstTriageParty').condition('settingValue', me).list())
            triaged.add(row.workEffortId)
        if (!triaged.size) return
        const open = Array.from(ec.entity.find('mantle.request.Request').condition('rootWorkEffortId', 'in', Array.from(triaged)).condition('statusId', 'ReqSubmitted')
                .orderBy('-requestDate').limit(50).list())
        if (!open.length) return
        const assigned = new Set(Array.from(ec.entity.find('mantle.request.RequestParty').condition('requestId', 'in', open.map((row) => row.requestId))
                .condition('roleTypeId', 'Assignee').conditionDate('fromDate', 'thruDate', null).list()).map((row) => row.requestId))
        const names = {}
        for (const request of open) {
            if (assigned.has(request.requestId) || items.filter((item) => item.kind === 'triage').length >= 10) continue
            const projectId = request.rootWorkEffortId
            if (!(projectId in names)) names[projectId] = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', projectId).one()?.workEffortName || projectId
            items.push(Object.assign({}, base, {kind: 'triage', requestId: request.requestId, title: request.requestName || request.requestId,
                priority: request.priority ?? null, statusId: request.statusId,
                record: {recordEntityName: 'mantle.work.effort.WorkEffort', recordId: projectId, recordName: names[projectId]}}))
        }
    } finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
})

templateList = []
for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetProject').condition('isTemplate', 'Y')
        .orderBy('workEffortName').limit(500).list()) {
    if (organizationPartyId && row.ownerPartyId && row.ownerPartyId !== organizationPartyId && ec.entity.find('mantle.work.effort.WorkEffortParty')
            .condition('workEffortId', row.workEffortId).condition('partyId', organizationPartyId).conditionDate('fromDate', 'thruDate', null).count() === 0) continue
    const id = row.workEffortId
    templateList.push({workEffortId: id, workEffortName: row.workEffortName || id, description: row.description || '', purposeEnumId: row.purposeEnumId || null,
        itemCount: ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', id).condition('workEffortTypeEnumId', 'WetTask').count(),
        milestoneCount: ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', id).condition('workEffortTypeEnumId', 'WetMilestone').count(),
        memberCount: ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', id).conditionDate('fromDate', 'thruDate', null).count(),
        usedCount: ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', id).condition('workEffortAssocTypeEnumId', 'WeatBasedOn').count()})
}

if (ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one() != null) {
    ec.message.addError(ec.resource.expand('The key ${workEffortId} is taken', '', {workEffortId})); return }
if (baseWorkEffortId) {
    const base = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', baseWorkEffortId).one()
    if (base == null || base.workEffortTypeEnumId !== 'WetProject') { ec.message.addError(ec.resource.expand('Project ${baseWorkEffortId} not found', '', {baseWorkEffortId})); return }
    ec.service.sync().name('mantle.work.ProjectServices.clone#Project').parameters({baseWorkEffortId: baseWorkEffortId, workEffortId: workEffortId,
        workEffortName: workEffortName, isTemplate: 'Y', ownerPartyId: base.ownerPartyId || ownerPartyId || null,
        description: description || base.description || null}).call()
} else {
    ec.service.sync().name('mantle.work.ProjectServices.create#Project').parameters({workEffortId: workEffortId, workEffortName: workEffortName,
        isTemplate: 'Y', ownerPartyId: ownerPartyId || null, description: description || null, visibilityEnumId: 'WevGeneral'}).call()
}

milestone = null; gate = null; canView = false; canRequest = false; canDecide = false; canSetGate = false; isApprover = false
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    if (row != null && row.workEffortTypeEnumId === 'WetMilestone' && row.rootWorkEffortId) {
        const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
        const all = !!vis.allProjects
        const projectId = row.rootWorkEffortId
        const settings = {}
        for (const setting of ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', workEffortId).list())
            settings[setting.settingTypeEnumId] = setting.settingValue
        const approverPartyId = settings.WstApproverParty || null
        const userPartyId = vis.userPartyId || null
        isApprover = !!userPartyId && userPartyId === approverPartyId
        // the approver sees the gate of a project it does not otherwise see, but a client contact only of its client projects
        // (impl-projects.md P10)
        canView = all || Array.from(vis.visibleProjectIds || []).includes(projectId) || (isApprover && !vis.isClient)
        if (canView) {
            const manages = all || Array.from(vis.managedProjectIds || []).includes(projectId)
                    || (Array.from(vis.visibleProjectIds || []).includes(projectId) && ec.user.hasPermission('MILESTONE_APPROVE'))
            canSetGate = manages
            canRequest = manages || Array.from(vis.memberProjectIds || []).includes(projectId)
            canDecide = manages || isApprover
            milestone = row.getMap()
            const latest = Array.from(ec.entity.find('mantle.work.effort.WorkEffortApproval').condition('workEffortId', workEffortId)
                    .orderBy('-requestedDate').orderBy('-workEffortApprovalId').limit(1).list())[0] || null
            const party = approverPartyId ? ec.entity.find('mantle.party.PartyDetail').condition('partyId', approverPartyId).one() : null
            gate = {required: settings.WstApprovalRequired === 'Y', approverPartyId: approverPartyId,
                approverName: party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || approverPartyId) : '',
                approval: latest ? latest.getMap() : null, approved: latest?.statusId === 'WeaApproved', awaiting: latest?.statusId === 'WeaRequested'}
        }
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (need === 'none') return
if (!canView) { ec.message.addError(ec.resource.expand('Milestone ${workEffortId} is not available', '', {workEffortId})); return }
if (need === 'request' && !canRequest) ec.message.addError(ec.l10n.localize('Only the project team asks for an approval'))
else if (need === 'decide' && !canDecide) ec.message.addError(ec.l10n.localize('Only the approver, or one who manages the project for them, decides'))
else if (need === 'gate' && !canSetGate) ec.message.addError(ec.l10n.localize('Only those who manage the project set its gates'))

const access = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneApprovalAccess').parameters({workEffortId: workEffortId, need: 'gate'}).call() || {}
if (ec.message.hasError()) return
const required = approvalRequired === 'Y' || approvalRequired === true || approvalRequired === 'true'
if (!required && access.gate.awaiting) { ec.message.addError(ec.l10n.localize('An approval is waiting: cancel it before taking the gate off')); return }
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (approverPartyId) {
        const onProject = ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', access.milestone.rootWorkEffortId)
                .condition('partyId', approverPartyId).conditionDate('fromDate', 'thruDate', null).count() > 0
        if (!onProject) { ec.message.addError(ec.l10n.localize('The approver is someone on the project: a manager or a client contact')); return }
    }
    if (required && !approverPartyId && !access.gate.approverPartyId) { ec.message.addError(ec.l10n.localize('Choose the approver')); return }
    ec.service.sync().name('mantle.work.ProjectServices.store#ProjectSetting').parameters({workEffortId: workEffortId,
        settingTypeEnumId: 'WstApprovalRequired', settingValue: required ? 'Y' : 'N'}).call()
    if (approverPartyId != null) ec.service.sync().name('mantle.work.ProjectServices.store#ProjectSetting').parameters({workEffortId: workEffortId,
        settingTypeEnumId: 'WstApproverParty', settingValue: approverPartyId || ''}).call()
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneApprovalAccess').parameters({workEffortId: workEffortId, need: 'request'}).call() || {}
if (ec.message.hasError()) return
const gate = access.gate
if (!gate.required) { ec.message.addError(L('The milestone needs no approval: set its gate first')); return }
if (!gate.approverPartyId) { ec.message.addError(L('The gate has no approver')); return }
if (gate.awaiting) { ec.message.addError(L('An approval is already waiting')); return }
if (['WeComplete', 'WeClosed', 'WeCancelled'].includes(access.milestone.statusId)) { ec.message.addError(L('The milestone is not open')); return }
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    workEffortApprovalId = ec.service.sync().name('create#mantle.work.effort.WorkEffortApproval').parameters({workEffortId: workEffortId,
        approverPartyId: gate.approverPartyId, statusId: 'WeaRequested', workEffortContentId: workEffortContentId || null,
        requestedByUserId: ec.user.userId || null, requestedDate: ec.user.nowTimestamp, requestComments: comments || null}).call()?.workEffortApprovalId
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (!ec.message.hasError() && workEffortApprovalId)
    ec.service.sync().name('mantle.work.ProjectServices.notify#MilestoneApproval').parameters({workEffortApprovalId: workEffortApprovalId, change: 'requested'}).call()

projectMoved = false
const L = (text) => ec.l10n.localize(text)
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const request = workEffortApprovalId ? ec.entity.find('mantle.work.effort.WorkEffortApproval').condition('workEffortApprovalId', workEffortApprovalId).forUpdate(true).one()
        : Array.from(ec.entity.find('mantle.work.effort.WorkEffortApproval').condition('workEffortId', workEffortId || '_NA_').condition('statusId', 'WeaRequested')
            .orderBy('-requestedDate').forUpdate(true).list())[0] || null
    if (request == null) { ec.message.addError(L('No approval waits on this milestone')); return }
    workEffortApprovalId = request.workEffortApprovalId
    const access = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneApprovalAccess').parameters({workEffortId: request.workEffortId, need: 'decide'}).call() || {}
    if (ec.message.hasError()) return
    if (request.statusId !== 'WeaRequested') { ec.message.addError(L('This approval was decided already')); return }
    const userPartyId = ec.user.userAccount?.partyId || null
    ec.service.sync().name('update#mantle.work.effort.WorkEffortApproval').parameters({workEffortApprovalId: workEffortApprovalId, statusId: 'WeaApproved',
        decidedByUserId: ec.user.userId || null, decidedDate: ec.user.nowTimestamp, decisionComments: comments || null,
        recordedFor: userPartyId && userPartyId === request.approverPartyId ? 'N' : 'Y'}).call()
    if (ec.message.hasError()) return
    const milestone = access.milestone
    if (!['WeComplete', 'WeClosed', 'WeCancelled'].includes(milestone.statusId)) {
        ec.service.sync().name('mantle.work.ProjectServices.update#Milestone').parameters({workEffortId: milestone.workEffortId, statusId: 'WeComplete'}).call()
        if (ec.message.hasError()) return
    }
    // the estimate approved moves the project on: In Planning to Approved, its open or proposed orders approved
    const estimateId = ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', milestone.rootWorkEffortId)
            .condition('settingTypeEnumId', 'WstEstimateMilestone').one()?.settingValue
    if (estimateId && estimateId === milestone.workEffortId) {
        const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', milestone.rootWorkEffortId).one()
        if (project?.statusId === 'WeInPlanning') {
            ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters({workEffortId: project.workEffortId, statusId: 'WeApproved'}).call()
            if (ec.message.hasError()) return
            projectMoved = true
        }
        const orderIds = Array.from(new Set(Array.from(ec.entity.find('mantle.order.OrderItemWorkEffort').condition('workEffortId', project.workEffortId).list())
                .map((link) => link.orderId)))
        for (const orderId of orderIds) {
            const header = ec.entity.find('mantle.order.OrderHeader').condition('orderId', orderId).one()
            if (!header || !['OrderOpen', 'OrderProposed'].includes(header.statusId)) continue
            // placed (from the quote), then approved unless the store approved it on placing
            ec.service.sync().name('mantle.order.OrderServices.update#OrderStatus').parameters({orderId: orderId, statusId: 'OrderPlaced',
                placedDate: ec.user.nowTimestamp}).call()
            if (ec.message.hasError()) return
            if (ec.entity.find('mantle.order.OrderHeader').condition('orderId', orderId).one()?.statusId === 'OrderPlaced')
                ec.service.sync().name('mantle.order.OrderServices.update#OrderStatus').parameters({orderId: orderId, statusId: 'OrderApproved',
                    approvedDate: ec.user.nowTimestamp}).call()
            if (ec.message.hasError()) return
        }
    }
