    }
    const milestone = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', row.workEffortId).one()
    const project = milestone ? ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', milestone.rootWorkEffortId).one() : null
    const requester = row.requestedByUserId ? ec.entity.find('moqui.security.UserAccount').condition('userId', row.requestedByUserId).one() : null
    const message = {workEffortApprovalId: workEffortApprovalId, workEffortId: row.workEffortId, milestoneName: milestone?.workEffortName || row.workEffortId,
        rootWorkEffortId: milestone?.rootWorkEffortId || null, projectName: project?.workEffortName || milestone?.rootWorkEffortId || '',
        approverName: nameOf(row.approverPartyId), requesterName: requester?.userFullName || requester?.username || '',
        actorName: ec.user.userAccount?.userFullName || ec.user.username || '',
        decision: {approved: L('approved'), refused: L('refused'), cancelled: L('withdrawn'), requested: L('requested')}[change] || change,
        reason: reason || '', reasonSuffix: reason ? ': ' + reason : ''}
    let topic, userIds = []
    if (change === 'requested') {
        topic = 'MilestoneApproval'
        userIds = Array.from(ec.entity.find('moqui.security.UserAccount').condition('partyId', row.approverPartyId || '_NA_').list())
                .filter((account) => account.disabled !== 'Y' && account.userId !== ec.user.userId).map((account) => account.userId)
    } else {
        topic = 'MilestoneDecision'
