estimate = null; estimateHtml = ''
const L = (text) => ec.l10n.localize(text)
if (!(ec.user.userId && (ec.user.isInGroup('ADMIN') || ec.user.hasPermission('TIME_ENTRY_RATE')))) { ec.message.addError(L('Only those who manage money see the estimate')); return }
const levels = Math.max(1, Math.min(4, Number(depth || 2)))
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    if (!project || project.workEffortTypeEnumId !== 'WetProject' || !(vis.allProjects || Array.from(vis.visibleProjectIds || []).includes(workEffortId))) {
        ec.message.addError(ec.resource.expand('Project ${workEffortId} is not available', '', {workEffortId})); return }
    const nameOf = (partyId) => {
        const party = partyId ? ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one() : null
        return party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || partyId) : ''
    }
    const partyOf = (roles) => Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', workEffortId)
            .condition('roleTypeId', 'in', roles).conditionDate('fromDate', 'thruDate', null).orderBy('fromDate').list())[0]?.partyId || null
    const clientPartyId = partyOf(['Customer', 'CustomerBillTo'])
    const vendorPartyId = partyOf(['Vendor', 'VendorBillFrom'])
    const uom = project.costUomId || (vendorPartyId ? ec.entity.find('mantle.ledger.config.PartyAcctgPreference').condition('organizationPartyId', vendorPartyId).one()?.baseCurrencyUomId : null) || 'USD'
    const rateOut = ec.service.sync().name('mantle.work.TimeServices.find#RateAmount').parameters({rateTypeEnumId: 'RatpStandard', ratePurposeEnumId: 'RaprClient',
        rateCurrencyUomId: uom, workEffortId: workEffortId}).call() || {}
