    const items = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', workEffortId).condition('workEffortTypeEnumId', 'WetTask')
            .condition('statusId', 'not-equals', 'WeCancelled').selectField('workEffortId,parentWorkEffortId,workEffortName,estimatedWorkTime,sequenceNum,statusId')
            .limit(20000).list()).map((row) => row.getMap())
    const children = {}
    const ids = new Set(items.map((item) => item.workEffortId))
    for (const item of items) {
        const parent = item.parentWorkEffortId && ids.has(item.parentWorkEffortId) ? item.parentWorkEffortId : ''
        ;(children[parent] || (children[parent] = [])).push(item)
    }
    const order = (a, b) => Number(a.sequenceNum ?? 0) - Number(b.sequenceNum ?? 0) || String(a.workEffortId).localeCompare(String(b.workEffortId), undefined, {numeric: true})
    const rollup = {}
    const hoursOf = (item) => {
        if (item.workEffortId in rollup) return rollup[item.workEffortId]
        const kids = children[item.workEffortId] || []
        const value = kids.length ? kids.reduce((total, kid) => total.add(hoursOf(kid)), toDecimal(0)) : toDecimal(item.estimatedWorkTime ?? 0)
        rollup[item.workEffortId] = value
        return value
    }
