    const money = (value) => value == null ? '' : ec.l10n.formatCurrency(value, uom)
    const lines = []
    const walk = (parentId, level) => {
        for (const item of (children[parentId] || []).slice().sort(order)) {
            const hours = hoursOf(item)
            const amount = rate != null ? hours.multiply(rate).setScale(2, 'HALF_UP') : null
            lines.push({workEffortId: item.workEffortId, workEffortName: item.workEffortName || item.workEffortId, level: level, hours: hours,
                hoursText: fmtHours(hours), amount: amount, amountText: money(amount)})
            if (level < levels) walk(item.workEffortId, level + 1)
