    const totalAmount = rate != null ? totalHours.multiply(rate).setScale(2, 'HALF_UP') : null
    const milestones = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', workEffortId).condition('workEffortTypeEnumId', 'WetMilestone')
            .condition('statusId', 'not-equals', 'WeCancelled').orderBy('estimatedCompletionDate').list()).map((row) => ({workEffortId: row.workEffortId,
        workEffortName: row.workEffortName || row.workEffortId, dueText: row.estimatedCompletionDate != null ? ec.l10n.format(row.estimatedCompletionDate, 'MMM d, yyyy') : ''}))
    const orderLines = []
    for (const link of ec.entity.find('mantle.order.OrderItemWorkEffort').condition('workEffortId', workEffortId).list()) {
        const item = ec.entity.find('mantle.order.OrderItem').condition({orderId: link.orderId, orderItemSeqId: link.orderItemSeqId}).one()
        if (!item) continue
        const header = ec.entity.find('mantle.order.OrderHeader').condition('orderId', link.orderId).one()
        const total = toDecimal(item.quantity ?? 1).multiply(toDecimal(item.unitAmount ?? 0)).setScale(2, 'HALF_UP')
        orderLines.push({orderId: link.orderId, orderItemSeqId: link.orderItemSeqId, description: item.itemDescription || link.orderId,
            quantityText: ec.l10n.format(item.quantity ?? 1, '#,##0.##'), total: total, totalText: ec.l10n.formatCurrency(total, header?.currencyUomId || uom)})
    }
    const today = ec.l10n.format(ec.user.nowTimestamp, 'MMM d, yyyy')
    estimate = {workEffortId: workEffortId, projectName: project.workEffortName || workEffortId, description: project.description || '',
        clientPartyId: clientPartyId, clientName: nameOf(clientPartyId), vendorPartyId: vendorPartyId, vendorName: nameOf(vendorPartyId),
        startText: project.estimatedStartDate != null ? ec.l10n.format(project.estimatedStartDate, 'MMM d, yyyy') : '',
        dueText: project.estimatedCompletionDate != null ? ec.l10n.format(project.estimatedCompletionDate, 'MMM d, yyyy') : '',
        depth: levels, currencyUomId: uom, rate: rate, rateText: rate != null ? money(rate) + ' / h' : '', hasRate: rate != null, lineList: lines, milestoneList: milestones,
        orderLineList: orderLines, totalHours: totalHours, totalHoursText: fmtHours(totalHours), totalAmount: totalAmount, totalAmountText: money(totalAmount), dateText: today}
    const enc = (text) => String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
    const row = (label, value) => value ? '<tr><td class="field-title">' + enc(L(label)) + '</td><td class="field-value">' + enc(value) + '</td></tr>' : ''
    let html = '<table style="width:100%"><tr><td style="vertical-align:top"><div class="box-header">' + enc(estimate.vendorName) + '</div></td>'
        + '<td style="vertical-align:top;text-align:right"><div class="box-header">' + enc(L('Estimate')) + '</div><table class="field" style="margin-left:auto">'
        + row('Project', estimate.projectName + ' (' + workEffortId + ')') + row('For', estimate.clientName) + row('Date', today) + row('Start', estimate.startText)
        + row('Target date', estimate.dueText) + row('Rate', estimate.rateText) + '</table></td></tr></table>'
        + (estimate.description ? '<p>' + enc(estimate.description) + '</p>' : '')
        + '<div class="group-title" style="margin-top:8pt">' + enc(L('Work')) + '</div><table class="list"><tr><th>' + enc(L('Work item')) + '</th><th style="text-align:right">'
        + enc(L('Hours')) + '</th><th style="text-align:right">' + enc(L('Amount')) + '</th></tr>'
        + lines.map((line) => '<tr><td style="padding-left:' + ((line.level - 1) * 14 + 4) + 'px' + (line.level === 1 ? ';font-weight:bold' : '') + '">' + enc(line.workEffortName)
            + '</td><td style="text-align:right;white-space:nowrap">' + enc(line.hoursText) + '</td><td style="text-align:right;white-space:nowrap">' + enc(line.amountText) + '</td></tr>').join('')
        + '<tr><td style="font-weight:bold">' + enc(L('Total')) + '</td><td style="text-align:right;font-weight:bold">' + enc(estimate.totalHoursText)
        + '</td><td style="text-align:right;font-weight:bold">' + enc(estimate.totalAmountText) + '</td></tr></table>'
    if (!estimate.hasRate) html += '<p>' + enc(L('The project has no client rate: the amounts are left out.')) + '</p>'
    if (orderLines.length) html += '<div class="group-title" style="margin-top:8pt">' + enc(L('Order')) + '</div><table class="list"><tr><th>' + enc(L('Line')) + '</th><th>'
        + enc(L('Description')) + '</th><th style="text-align:right">' + enc(L('Amount')) + '</th></tr>' + orderLines.map((line) => '<tr><td>' + enc(line.orderId + ' ' + line.orderItemSeqId)
        + '</td><td>' + enc(line.description) + '</td><td style="text-align:right;white-space:nowrap">' + enc(line.totalText) + '</td></tr>').join('') + '</table>'
    if (milestones.length) html += '<div class="group-title" style="margin-top:8pt">' + enc(L('Milestones')) + '</div><table class="list"><tr><th>' + enc(L('Milestone'))
        + '</th><th>' + enc(L('Due')) + '</th></tr>' + milestones.map((one) => '<tr><td>' + enc(one.workEffortName) + '</td><td>' + enc(one.dueText) + '</td></tr>').join('') + '</table>'
    estimateHtml = html
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

const L = (text) => ec.l10n.localize(text)
const out = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectEstimate').parameters({workEffortId: workEffortId, depth: depth}).call() || {}
if (ec.message.hasError()) return
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
if (!(vis.allProjects || Array.from(vis.managedProjectIds || []).includes(workEffortId) || ec.user.hasPermission('MILESTONE_APPROVE'))) {
    ec.message.addError(L('Only those who manage the project send its estimate')); return }
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const approver = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', workEffortId).condition('roleTypeId', 'ClientManager')
            .conditionDate('fromDate', 'thruDate', null).orderBy('fromDate').list())[0]?.partyId || out.estimate.clientPartyId
    if (!approver) { ec.message.addError(L('The project has no client to approve its estimate')); return }
    milestoneId = ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', workEffortId).condition('settingTypeEnumId', 'WstEstimateMilestone').one()?.settingValue || null
    const existing = milestoneId ? ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', milestoneId).one() : null
    if (!existing || existing.workEffortTypeEnumId !== 'WetMilestone' || existing.statusId === 'WeCancelled') {
        milestoneId = ec.service.sync().name('mantle.work.ProjectServices.create#Milestone').parameters({rootWorkEffortId: workEffortId, workEffortName: L('Estimate'),
            description: L('The client approves the project estimate through this milestone\'s gate.'), statusId: 'WeInProgress',
            estimatedCompletionDate: ec.user.nowTimestamp}).call()?.workEffortId
        if (ec.message.hasError()) return
        ec.service.sync().name('mantle.work.ProjectServices.store#ProjectSetting').parameters({workEffortId: workEffortId, settingTypeEnumId: 'WstEstimateMilestone',
            settingValue: milestoneId}).call()
    } else if (['WeComplete', 'WeClosed'].includes(existing.statusId)) {
        // a new estimate after an approved one: the milestone opens again for the new approval
        ec.service.sync().name('mantle.work.ProjectServices.update#Milestone').parameters({workEffortId: milestoneId, statusId: 'WeInProgress'}).call()
        if (ec.message.hasError()) return
    }
    for (const [type, value] of [['WstApprovalRequired', 'Y'], ['WstApproverParty', approver]]) {
        const current = ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', milestoneId).condition('settingTypeEnumId', type).one()
        if (type === 'WstApproverParty' && current?.settingValue) continue
        ec.service.sync().name('mantle.work.ProjectServices.store#ProjectSetting').parameters({workEffortId: milestoneId, settingTypeEnumId: type, settingValue: value}).call()
    }
    if (ec.message.hasError()) return
    const root = String(ec.user.getPreference('mantle.content.root') || 'dbresource://mantle/content').replace(/\/+$/, '')
    const stamp = ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd-HHmmss')
    const location = root + '/work/' + milestoneId + '/estimate-' + stamp + '.html'
    const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + String(L('Estimate')) + '</title><style>body{font-family:sans-serif;font-size:10pt}'
        + 'table.list{border-collapse:collapse;width:100%}table.list th,table.list td{border-bottom:1px solid #ccc;padding:3px 4px;text-align:left}'
        + '.box-header{font-size:14pt;font-weight:bold}.group-title{font-weight:bold;margin:6pt 0 2pt}td.field-title{color:#666;padding-right:8px}</style></head><body>'
        + out.estimateHtml + '</body></html>'
    ec.resource.getLocationReference(location).putText(html)
    workEffortContentId = ec.service.sync().name('create#mantle.work.effort.WorkEffortContent').parameters({workEffortId: milestoneId, contentTypeEnumId: 'WectEstimate',
        contentLocation: location, description: ec.resource.expand('Estimate of ${projectName}: ${hours} h, ${amount}', '', {projectName: out.estimate.projectName,
            hours: out.estimate.totalHoursText, amount: out.estimate.totalAmountText || L('no rate')}), contentDate: ec.user.nowTimestamp, userId: ec.user.userId || null}).call()?.workEffortContentId
    if (ec.message.hasError()) return
    ec.service.sync().name('mantle.work.ProjectServices.cancel#MilestoneApproval').parameters({workEffortId: milestoneId}).call()
    if (ec.message.hasError()) return
    workEffortApprovalId = ec.service.sync().name('mantle.work.ProjectServices.request#MilestoneApproval').parameters({workEffortId: milestoneId,
        comments: comments || null, workEffortContentId: workEffortContentId}).call()?.workEffortApprovalId
    if (ec.message.hasError()) return
    // the project's open orders are quotes now
    for (const orderId of Array.from(new Set(Array.from(ec.entity.find('mantle.order.OrderItemWorkEffort').condition('workEffortId', workEffortId).list()).map((link) => link.orderId)))) {
        const header = ec.entity.find('mantle.order.OrderHeader').condition('orderId', orderId).one()
        if (header?.statusId === 'OrderOpen') ec.service.sync().name('mantle.order.OrderServices.update#OrderStatus').parameters({orderId: orderId, statusId: 'OrderProposed'}).call()
        if (ec.message.hasError()) return
    }
    // the client approver is told by email, with the estimate (it has no tray); a failure is logged, the estimate stays sent
    emailedAddressList = []
    ec.message.pushErrors()
    try {
        emailedAddressList = Array.from(ec.service.sync().name('mantle.work.ProjectServices.send#EstimateEmail').parameters({workEffortId: workEffortId,
            approverPartyId: approver, milestoneId: milestoneId, estimateHtml: out.estimateHtml, comments: comments || null,
            totalHoursText: out.estimate.totalHoursText || '', totalAmountText: out.estimate.totalAmountText || ''}).call()?.emailedAddressList || [])
    } catch (err) {
        ec.logger.error(`Estimate of ${workEffortId}: email to the approver not sent: ${err && err.message ? err.message : err}`)
    } finally {
        if (ec.message.hasError()) ec.logger.error(`Estimate of ${workEffortId}: email to the approver not sent: ${ec.message.getErrorsString()}`)
        ec.message.clearErrors()
        ec.message.popErrors()
