    const actualCost = D(project.actualCost)
    summary = {workEffortId: workEffortId, currencyUomId: uom, clientPartyId: clientPartyId, clientName: nameOf(clientPartyId), vendorPartyId: vendorPartyId,
        hoursBudget: project.totalTimeAllowed != null ? D(project.totalTimeAllowed) : null, clientBudget: project.totalClientCostAllowed != null ? budget : null,
        estimatedHours: D(project.estimatedWorkTime), actualHours: D(project.actualWorkTime), remainingHours: D(project.remainingWorkTime),
        actualCost: actualCost, actualClientCost: actualClient, profit: actualClient.subtract(actualCost),
        budgetUsedPercent: budget.isZero() ? null : actualClient.multiply(toDecimal(100)).divide(budget).setScale(1, 'HALF_UP'),
        budgetRemaining: project.totalClientCostAllowed != null ? budget.subtract(actualClient) : null,
        hoursUsedPercent: D(project.totalTimeAllowed).isZero() ? null : D(project.actualWorkTime).multiply(toDecimal(100)).divide(D(project.totalTimeAllowed)).setScale(1, 'HALF_UP'),
        overBudget: !!stats.clientActualOverBudget, overHours: !!stats.actualPlusRemainingOverTimeBudget && !D(project.totalTimeAllowed).isZero(),
        projectWarning: !!stats.projectWarning, projectDanger: !!stats.projectDanger,
        invoiced: invoiced, paid: paid, openReceivable: open, invoiceList: invoices, expenseTotal: expenseTotal, expenseBilled: expenseBilled, expenseList: expenses,
        unbilledHours: unbilled ? D(unbilled.hours) : zero, unbilledAmount: unbilled ? D(unbilled.amount) : zero, readyAmount: unbilled ? D(unbilled.readyAmount) : zero,
        readyHours: unbilled ? D(unbilled.readyHours) : zero, unbilledExpenses: unbilled ? D(unbilled.expenseAmount) : zero, unbilled: unbilled,
        contracted: contracted, sharesDue: sharesDue, sharesBilled: sharesBilled, shareList: shares, lineList: lines}
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
